    ZIGZAG_FREQUENCY_DEFAULT: 1,
    // Bezier curve parameters
    BEZIER_CONTROL_POINT_OFFSET: 0.3,
    BEZIER_POINT_DENSITY: 8, // Lowered from 20 to reduce segment count and improve rendering
