/**
 * @file A run: the object a started computation hands back.
 *
 * Starting an algorithm returns a `Run` rather than a bare promise, because everything a caller
 * needs to behave well is a fact about the running work and has nowhere else to live: what it
 * is called, how far it has got, whether it can be stopped, what qualifies the numbers it will
 * produce, and -- once it finishes -- the result itself. A call that returns nothing forces
 * every consumer to go looking for its own answer somewhere else, and an analysis that cannot be
 * watched or stopped is unusable on a graph big enough to be worth analysing.
 *
 * Nothing here reaches Babylon.js, Lit or the DOM: a run is plain data plus a promise, published
 * from the Node-safe `./session` entry point.
 *
 * One member of the design's run object is deliberately absent until the work that defines it
 * lands, rather than being stubbed with a placeholder type: `command`, the journalled command a
 * run was started from, which arrives with the command union.
 */

import type {
    AlgorithmKey,
    EdgeId,
    EdgeReading,
    FieldDescriptor,
    LayerId,
    NodeId,
    PaletteId,
    ResultShape,
    RunId,
    Scope,
    ScopeInput,
    SetId,
} from "../../catalog/types";
import type { GraphtyErrorCode } from "../../errors/codes";
import type { GraphtyError } from "../../errors/GraphtyError";
import type { JournalId } from "../journal";
import type { ResultSummary, RunResult } from "../results/types";
import type { CodedFact } from "../shared";
import type { StyleSuggestion } from "../styles/derive";
import type { CaveatCode, PartialCode } from "./caveatFacts";

// ---------------------------------------------------------------------------------------------
// Identity
// ---------------------------------------------------------------------------------------------

/**
 * What a run id is allowed to look like.
 *
 * An id ends up inside a style selector, a saved document and an export filename, so it is
 * restricted to lower-case letters, digits, hyphens and underscores, starting with a letter.
 */
export const RUN_ID_PATTERN = /^[a-z][a-z0-9_-]*$/;

/**
 * Tell whether a string can be used as a run id.
 * @param value - The value to test.
 * @returns True when the value is a string matching the run-id pattern.
 */
export function isRunId(value: unknown): value is RunId {
    return typeof value === "string" && RUN_ID_PATTERN.test(value);
}

// ---------------------------------------------------------------------------------------------
// Status and progress
// ---------------------------------------------------------------------------------------------

/**
 * Where a run is in its life.
 *
 * "canceled" and "failed" are separate because a consumer treats them differently: a cancel is
 * something a person did and needs no apology, a failure is something the consumer has to
 * report. A time-boxed run that stopped early is neither -- it SUCCEEDS with `partial` set.
 *
 * "removed" is a finished run that undo has taken out of the project, or that `runs.remove`
 * took away: its handle reports no result until a redo brings the run back.
 */
export const RUN_STATUSES = ["queued", "running", "succeeded", "failed", "canceled", "removed"] as const;

/** Where a run is in its life. */
export type RunStatus = (typeof RUN_STATUSES)[number];

/** The statuses a run never leaves once it reaches them. */
export const TERMINAL_RUN_STATUSES: readonly RunStatus[] = Object.freeze([
    "succeeded",
    "failed",
    "canceled",
    "removed",
]);

/**
 * Tell whether a value is one of the run statuses.
 * @param value - The value to test.
 * @returns True when the value is a member of RUN_STATUSES.
 */
export function isRunStatus(value: unknown): value is RunStatus {
    return typeof value === "string" && (RUN_STATUSES as readonly string[]).includes(value);
}

/**
 * Tell whether a run in this status has stopped for good.
 * @param status - The status to test.
 * @returns True when nothing further will happen to the run.
 */
export function isTerminalRunStatus(status: RunStatus): boolean {
    return TERMINAL_RUN_STATUSES.includes(status);
}

/**
 * The moments a watcher is told about: the four of a run's own life, and the two of history.
 *
 * Coarser than {@link RunStatus} on purpose: a status bar draws the same thing for a run that
 * failed and one that was cancelled -- it stops showing progress and reads the record -- so the
 * distinction belongs in the record the notification carries rather than in the notification's
 * own name. "removed" and "restored" are an undo, a redo or a restore taking a finished run out
 * of the project and putting it back; nothing was computed for either.
 */
export const RUN_PHASES = ["queued", "start", "progress", "end", "removed", "restored"] as const;

/** Which moment in a run's life a notification is about. */
export type RunPhase = (typeof RUN_PHASES)[number];

/**
 * What a run notification carries.
 *
 * The record rather than the run: this crosses a DOM event and a worker boundary, where a live
 * object with a `cancel()` on it cannot go. A consumer that wants to cancel looks the run up by
 * `record.id`.
 */
export interface RunChange {
    /** The run, as a frozen snapshot. */
    readonly run: RunRecord;
    /** Which moment this is. */
    readonly phase: RunPhase;
    /** What moved it: a command for the run's own life, or an undo, a redo or a restore. */
    readonly cause: "command" | "undo" | "redo" | "restore" | "rollback";
    /**
     * How many times this run id has been executed, so a watcher keyed on the id can tell an old
     * execution's `end` from a new one's.
     */
    readonly generation: number;
}

/**
 * How far a run has got.
 *
 * `fraction` is null while the work is indeterminate, and it stays null: a percentage invented
 * for a progress bar that has nothing to measure is worse than a spinner, because it tells the
 * reader a lie they will time their patience against.
 */
export interface Progress {
    /** What the run is doing now, in words a progress line can show. */
    readonly phase: string;
    /** Whether the total is known. False means the run cannot say how much is left. */
    readonly determinate: boolean;
    /** How many units are done. */
    readonly completed: number;
    /** How many units there are in total, or null when that is not knowable. */
    readonly total: number | null;
    /** How far along, from 0 to 1, or null when indeterminate. Never a fabricated number. */
    readonly fraction: number | null;
    /** How much longer, in milliseconds, or null when that cannot be projected. */
    readonly etaMs: number | null;
    /** A sentence about the current step, when the run has one to offer. */
    readonly message?: string;
}

/** Why a finished run went out of date; see {@link StaleNote.reason}. */
export type StaleReason = "data-changed" | "scope-changed" | "window-moved";

/**
 * The time window a run over the visible graph was computed in, and what it left visible then.
 * Numbers only: `from` and `to` are epoch milliseconds (or ordinal values), half-open.
 */
export interface RunWindow {
    /** The attribute the window read. */
    readonly attribute: string;
    readonly from: number;
    readonly to: number;
    /** How many nodes were visible when the run resolved its scope. */
    readonly nodes: number;
    /** How many edges were visible when the run resolved its scope. */
    readonly edges: number;
}

/**
 * Why a run's numbers no longer describe what is on screen.
 *
 * This is DERIVED rather than tracked: the element compares the data digest and the scope digest
 * the run recorded against the graph's data and the current resolution of the same scope
 * specification, so "computed on 200 nodes, now showing 120" is answerable with the consumer
 * tracking nothing.
 */
export interface StaleNote {
    /**
     * Why the numbers no longer describe the graph: `data-changed` when the data the run read
     * was replaced or edited (a reload with new weights), `scope-changed` when the same data
     * resolves to other elements (a filter, the selection or a set changed), `window-moved` when
     * the run was computed in a time window and the window in force is another one (even when it
     * leaves the same nodes visible). A data change wins when both happened.
     */
    readonly reason: StaleReason;
    /**
     * With `reason: "window-moved"`: the window the run was computed in, `{ code: "window-moved",
     * params: { from, to, nodes, edges } }`.
     */
    readonly window?: CodedFact<"window-moved">;
    /** How many elements the run was computed over. */
    readonly ranOn: number;
    /** How many the same scope resolves to now. */
    readonly nowVisible: number;
    /** The scope specification, so a consumer can offer to re-run over it. */
    readonly scopeSpec: Scope;
}

// ---------------------------------------------------------------------------------------------
// Caveats: what qualifies the numbers
// ---------------------------------------------------------------------------------------------

/** The arithmetic a run's numbers were computed in. */
export type Precision = "f32" | "f64";

/** How edge direction was treated. */
export type RunDirection = "directed" | "undirected" | "as-loaded";

/** What an edge weight was taken to mean. */
export interface WeightMeaning {
    /** The attribute the weight was read from. */
    readonly attribute: string;
    /**
     * Whether a larger weight means further apart, more strongly connected, or more room for flow.
     *
     * OPEN UNION: later releases may add meanings.
     */
    readonly meaning: "distance" | "strength" | "capacity";
    /**
     * True when nobody stated the weight's meaning and the run read it as the meaning its
     * algorithm reads (a strength reader reads an unstated weight as a strength). Absent when the
     * meaning was stated, at load or in the run's `weight` option.
     */
    readonly assumed?: true;
}

/**
 * Why a run left a weight unread. `code` is `"weight.meaning-mismatch"`; `params.attribute` is the
 * column, `params.meaning` what the weight means (null when nobody said), and `params.reads` the
 * meaning the algorithm reads.
 */
export type WeightSkip = CodedFact<"weight.meaning-mismatch">;

/**
 * What qualifies a run's numbers.
 *
 * Caveats travel with the result rather than sitting in a graph-level bag of facts, because two
 * runs of the same algorithm on the same graph can differ in every one of them. A consumer
 * comparing a value against a saved one, or ranking two nodes whose scores are within a rounding
 * error, reads the qualification from the same object that carries the value.
 *
 * `precision` is the clearest case: a run on an accelerator computes in single precision and
 * reports "f32", a run on the CPU path reports "f64", and without it "why does this number
 * disagree with the one I had a minute ago" has no answer.
 */
export interface Caveats {
    /** Whether the numbers are exact, or an approximation the element chose above the cost cap. */
    readonly exact: boolean;
    /** How many elements the approximation sampled. Present only when `exact` is false. */
    readonly sampleSize?: number;
    /** The seed a sampled or randomised run used, so it can be reproduced. */
    readonly seed?: number | null;
    /** Whether an iterative algorithm reached its convergence threshold. */
    readonly converged?: boolean;
    /** How many iterations it took. */
    readonly iterations?: number;
    /** Whether the run covered every component or only the largest. */
    readonly componentScope?: "all" | "largest";
    /** Whether a visibility filter narrowed what the run looked at. */
    readonly filterScope?: boolean;
    /** Whether a time window narrowed what the run looked at. */
    readonly windowScope?: boolean;
    /** The time window a run over the visible graph was computed in, and its visible counts. */
    readonly window?: RunWindow;
    /** How edge direction was treated. */
    readonly direction: RunDirection;
    /**
     * The edge weight the run read -- the column and the meaning it was read as -- or null when it
     * read none. A run reads the weight the graph was loaded with unless its `weight` option says
     * otherwise.
     */
    readonly weight?: WeightMeaning | null;
    /**
     * Present when a weight was there and the run left it unread, because its meaning is not the
     * one the algorithm reads (a strength handed to a shortest path, which reads a distance): the
     * run then counts edges. See {@link WeightSkip}.
     */
    readonly weightSkipped?: WeightSkip;
    /** The arithmetic that produced these numbers. */
    readonly precision: Precision;
    /** Which method computed them, such as "dijkstra" or "brandes-sampled". */
    readonly method: string;
    /**
     * Why a run stopped before it finished, when it did, as a code and its values. Present when
     * the run resolved with `partial` set, whatever stopped it: a time box, a cancellation, a
     * batch that did not finish, or the algorithm's own iteration cap. Absent for a run an
     * extension stopped and explained only in words, in {@link Caveats.partialReason}.
     * @since 3.18.0
     */
    readonly partialCause?: CodedFact<PartialCode>;
    /**
     * Why a run stopped before it finished, as an English sentence. Present exactly when the run
     * resolved with `partial` set.
     * @deprecated Word {@link Caveats.partialCause} yourself. Removed in the next major.
     */
    readonly partialReason?: string;
    /**
     * Anything else a reader should know, one fact per remark, in the order a reader reads them.
     * See {@link CaveatCode} for every code and its parameters.
     * @since 3.18.0
     */
    readonly facts: readonly CodedFact<CaveatCode>[];
    /**
     * The same remarks as English sentences, followed by any sentence an extension wrote in words.
     * @deprecated Word {@link Caveats.facts} yourself. Removed in the next major.
     */
    readonly notes: readonly string[];
}

// ---------------------------------------------------------------------------------------------
// Scope, as a run records it
// ---------------------------------------------------------------------------------------------

/**
 * A scope specification resolved against the graph as it stands.
 *
 * Declared here because a run carries the scope it ran over and the scope API has not landed.
 * It moves to the scope module when that arrives; nothing should declare a second one in the
 * meantime.
 */
export interface ResolvedScope {
    /**
     * The nodes in scope. Lazy: built on the first read, then the same set on every read. It yields
     * each id as the graph holds it, but `has` takes an integer id written either way: with node
     * `34` in scope, `nodes.has("34")` is true.
     */
    readonly nodes: ReadonlySet<NodeId>;
    /** The edges in scope. Lazy: built on the first read, then the same set on every read. */
    readonly edges: ReadonlySet<EdgeId>;
    /** How many nodes are in scope. */
    readonly nodeCount: number;
    /** How many edges are in scope. */
    readonly edgeCount: number;
    /**
     * Equal digests mean equal scopes, which is how staleness is derived rather than tracked.
     * Versioned: `d1:` and 16 hex digits, comparable only within one session and store. Computed
     * on first read.
     */
    readonly digest: string;
    /** What was asked for, before it was resolved. */
    readonly spec: Scope;
    /** When it was resolved, as an ISO 8601 timestamp. */
    readonly resolvedAt: string;
}

/** The scope a run ran over, in the structured-cloneable form a record carries. */
export interface RunScopeRecord {
    /** What was asked for. */
    readonly spec: Scope;
    /** How many nodes it resolved to. */
    readonly nodes: number;
    /** How many edges it resolved to. */
    readonly edges: number;
    /** The digest the staleness comparison reads. */
    readonly digest: string;
    /**
     * The kept set a `{ set }` scope named, and its revision when the run resolved it, so a reader
     * can tell whether the set has been redefined since. Absent for every other scope.
     */
    readonly set?: {
        /** The kept set's id. */
        readonly id: SetId;
        /** The set's revision when the run resolved it. */
        readonly revision: string;
    };
    /** Which edges came with the scope's nodes. OPEN UNION, as {@link EdgeReading}. */
    readonly reading?: EdgeReading;
    /**
     * A digest of the graph's data (records, endpoints, weights) when the run resolved its
     * scope; a different one now means the data changed under the run. Absent when the session
     * records none.
     */
    readonly dataDigest?: string;
    /**
     * For a scope over the visible graph: the time window in force when it resolved, or null when
     * there was none. Absent for every other scope.
     */
    readonly window?: RunWindow | null;
}

/** What a run records about the set its scope named, beside the resolution. */
export type RunScopeFacts = Pick<RunScopeRecord, "set" | "reading" | "dataDigest" | "window">;

/** Which versions of which packages produced a result. */
export interface EngineVersions {
    /** The graphty-element version. */
    readonly element: string;
    /** The algorithms package version. */
    readonly algorithms: string;
    /** The layout package version. */
    readonly layout: string;
    /**
     * The versions of any registered extensions that produced these numbers, by catalogue key.
     *
     * WHY IT IS HERE. The three fixed fields above name the element and its two sibling packages,
     * which is everything when the element's own algorithm did the work. A run of a THIRD PARTY's
     * algorithm used to record those same three and nothing at all identifying the code that
     * actually computed the result -- which is the field's whole purpose. Filled from an optional
     * `static version` on the registered class, and absent when the class declares none.
     */
    readonly plugins?: Readonly<Record<string, string>>;
}

// ---------------------------------------------------------------------------------------------
// Starting a run
// ---------------------------------------------------------------------------------------------

/**
 * How a call joins the queue.
 *
 * "append" waits its turn. "replace" aborts the in-flight work of the same kind, rejecting its
 * promise with an AbortError. "now" runs beside the queue, and is refused for anything that
 * mutates.
 */
export const QUEUE_POLICIES = ["append", "replace", "now"] as const;

/** How a call joins the queue. */
export type QueuePolicy = (typeof QUEUE_POLICIES)[number];

/**
 * What any started work accepts.
 *
 * Declared beside `Progress` because `onProgress` is what makes it worth passing. It is the same
 * type the command executor takes when that lands; there is one of it, not two.
 */
export interface RunOptions {
    /** A signal that cancels the work. Cancelling rejects with an AbortError. */
    readonly signal?: AbortSignal;
    /** Called as the work advances, with the run's current progress. */
    readonly onProgress?: (progress: Progress) => void;
    /** How the call joins the queue. Defaults to "append". */
    readonly queue?: QueuePolicy;
    /** Ask what this would do and cost instead of doing it. Nothing is performed. */
    readonly dryRun?: boolean;
    /** Override the configured transition duration for this call only, in milliseconds. */
    readonly transitionMs?: number;
}

/**
 * What starting one algorithm accepts.
 *
 * `as` is the author-assigned id, and it is REQUIRED the moment anything that names the run is
 * persisted: a derived id is a function of the algorithm, the parameters and the scope, and a
 * saved document that referenced one would resolve differently against a different session.
 */
export interface StartOptions extends RunOptions {
    /**
     * What the run may look at. Defaults to the visible graph. An inline `{ define }` may name
     * edges by session edge id; the run records their stable form.
     */
    readonly scope?: ScopeInput;
    /** The seed for a randomised or sampled method, so a run can be reproduced. */
    readonly seed?: number;
    /**
     * Stop after this many milliseconds and publish what was computed.
     *
     * A run that hits its box RESOLVES with `partial` set and a reason in the caveats. A
     * stopped-early result is data, not a failure.
     */
    readonly timeBoxMs?: number;
    /** The id to give the run. Required for anything that will be saved. */
    readonly as?: RunId;
    /**
     * What the element paints on first completion. Set false to opt out of the encoding layer it
     * applies, or `{ size: true }` to size the nodes by a node measurement, or widen the edges by an
     * edge measurement, as well. See
     * {@link RunStyle}.
     */
    readonly style?: RunStyle;
    /** Refuse to approximate. Above the cost cap this fails rather than sampling. */
    readonly exact?: boolean;
    /** Ask for the approximate method at a chosen sample size. */
    readonly sample?: number;
    /**
     * Also apply the layers the run suggests, on top of the stack, in the same step as the run,
     * so one undo takes the run and those layers away together.
     */
    readonly applySuggestedStyles?: boolean;
    /**
     * Put back the layers this run added when it first completed that are no longer in the stack
     * (a reader deleted them), as they were suggested, in the same step as the run: one undo takes
     * them away again. A run that already answers the question is not computed again -- its stored
     * result paints the layers -- unless its parameters or the data changed, in which case it runs
     * and the layers come back on the new result. A layer still in the stack is left as it is.
     * {@link RunsApi.layers} says beforehand whether anything is missing.
     * @since 3.26.0
     */
    readonly restoreLayer?: boolean;
}

/**
 * Which of a run's layers the stack holds: what {@link RunsApi.layers} answers.
 * @since 3.26.0
 */
export interface RunLayers {
    /** The layers reading the run, as {@link RunsApi.bindings} lists them. */
    readonly present: readonly LayerId[];
    /**
     * What the run painted on its first completion that no layer reading the run paints any more:
     * what `start(..., { restoreLayer: true })` puts back. Empty when nothing is missing.
     */
    readonly missing: readonly StyleSuggestion[];
}

/**
 * What a run paints when it first completes.
 *
 * - `true`, or left off: the colour suggestion its result shape calls for.
 * - `false`: nothing. The numbers are published and no layer is added.
 * - `{ size }`: the colour suggestion, plus a size encoding of the same field. For a run whose
 *   result is a node measurement (shape `"node-metric"`: PageRank, degree, betweenness and the
 *   rest) that is a node size: `size: true` sizes nodes from 1 (the default node size, so the
 *   least important node looks unchanged) to 3. For a run whose result is an edge measurement
 *   (shape `"edge-metric"`: max flow, edge betweenness) it is an edge width: `size: true` draws
 *   edges from the default edge width to twice it. `size: [min, max]` uses that range, in the
 *   channel's own units. `size: false` or left off adds no size. For any other result shape the
 *   size is ignored, without an error, exactly as the colour suggestion itself depends on the
 *   shape.
 * - `{ name }`: what to call the layers it adds, in place of the run's label. An application that
 *   names algorithms in its own words passes the name its reader picked the algorithm by. Combines
 *   with `size`.
 *
 * Every layer this adds is scoped to the elements carrying the run's value, and is removed with
 * the run.
 */
export type RunStyle =
    | boolean
    | {
          readonly size?: boolean | readonly [min: number, max: number];
          readonly name?: string;
          /**
           * `"layers"`: a run that partitions the nodes (shape `"community"`: Louvain, Leiden, label
           * propagation, connected components) paints each group as a layer of its own instead of one
           * layer colouring every group: a folder named for the run (`name`, else the run's label)
           * holding one node layer per group, largest on top, each selecting `<group path> ==
           * <value>` and setting the colour the one layer would have painted that group. A re-run
           * keeps each layer on the group sharing most of its members and adds a layer at the bottom
           * of the folder for each new group, whether or not the re-run repeats the option (it
           * keeps the first start's `groupName`); removing the run removes the folder. Ignored for
           * any other result shape. Left off, the run paints one layer.
           * @since 3.29.0
           */
          readonly groups?: "layers";
          /**
           * What to call each group's layer when `groups` is `"layers"`; its value as text when
           * absent. `rank` is 1 for the largest group; `taken` lists the names the folder's
           * layers already go by, so a re-run's new group can be given a name no layer has. The
           * name is also given to the group's value (as `data.setValueLabel` gives one), so the
           * legend and every value list name the group as its layer is named, and the name
           * follows the group across a re-run.
           * @since 3.29.0
           */
          readonly groupName?: (group: RunGroup) => string;
          /**
           * The palettes the group layers may be colored from when `groups` is `"layers"`, in
           * order of preference: the first with a color for every group the run finds; when none
           * has, the first, its colors continued past its end. Absent, the colors are the ones the
           * run's single layer would have painted. Ignored without `groups`.
           * @since 3.32.0
           */
          readonly groupPalettes?: readonly PaletteId[];
      };

/**
 * One group of a run that partitions the nodes, as {@link RunStyle}'s `groupName` is asked about it.
 * @since 3.29.0
 */
export interface RunGroup {
    /** The group's value, as the run published it. */
    readonly value: unknown;
    /** Its place by size, 1 for the largest. */
    readonly rank: number;
    /** How many nodes it holds. */
    readonly size: number;
    /** The names of the layers already in the run's folder of groups. */
    readonly taken: readonly string[];
}

/** One member of a batch: the same thing `start` takes, as data. */
export interface RunSpec {
    /** Which algorithm to run. */
    readonly algorithm: AlgorithmKey;
    /** Its parameters. */
    readonly params?: Readonly<Record<string, unknown>>;
    /** What it may look at, as {@link StartOptions.scope}. */
    readonly scope?: ScopeInput;
    /** The seed for a randomised or sampled method. */
    readonly seed?: number;
    /** The id to give the run. */
    readonly as?: RunId;
    /** What the element paints on first completion; see {@link RunStyle}. */
    readonly style?: RunStyle;
}

/** How one member of a batch turned out. */
export interface BatchStep {
    /** Its position in the specification list. */
    readonly index: number;
    /** The run it started, absent when the member never started. */
    readonly runId?: RunId;
    /** Whether it succeeded. */
    readonly ok: boolean;
    /** Why it did not, when it did not. */
    readonly reason?: string;
}

/**
 * What a batch produced.
 *
 * A cancelled batch KEEPS the members that already completed: they are results somebody paid
 * for, and throwing them away because a later member was stopped would be the element deciding
 * on the consumer's behalf that partial work is worthless.
 */
export interface BatchResult {
    /** What the batch is called. */
    readonly label: string;
    /** How many members it had. */
    readonly total: number;
    /** How many finished. */
    readonly completed: number;
    /** Whether it stopped before every member finished. */
    readonly partial: boolean;
    /** How each member turned out, in specification order. */
    readonly steps: readonly BatchStep[];
}

// ---------------------------------------------------------------------------------------------
// The run
// ---------------------------------------------------------------------------------------------

/**
 * The one option an unnamed run's name was suggested by: a built-in algorithm names its result by
 * one setting worth telling two of its results apart by (PageRank's `dampingFactor`, Louvain's
 * `resolution`), once that setting leaves its default. A run's label is worded from it, the
 * algorithm's catalog name and the value.
 * @since 3.18.0
 */
export interface RunDistinction {
    /** The option's name, as the algorithm's catalog `options` spell it. */
    readonly option: string;
    /** The value the run used, canonicalized. */
    readonly value: unknown;
}

/**
 * A frozen, structured-cloneable snapshot of a run.
 *
 * This is what crosses a worker boundary, what an event carries, what the journal stores and
 * what an export embeds. It holds no functions and no live references, so it can be posted,
 * saved and diffed; `Run` is the live object, and `run.record` is this.
 */
export interface RunRecord {
    /** The run id. */
    readonly id: RunId;
    /**
     * What the run is called, computed by the element.
     * @deprecated Word the run from its `algorithm`, {@link RunRecord.distinguishedBy} and
     *   {@link RunRecord.siblingsDifferBy} yourself. Removed in the next major.
     */
    readonly label: string;
    /**
     * The option this run's name was suggested by, once it left its default: what tells it apart
     * from a run of the same algorithm at the defaults. Null for a run at the defaults, a run the
     * caller named with `as`, a batch, and a run of an algorithm registered with its own
     * `suggestedName`.
     * @since 3.18.0
     */
    readonly distinguishedBy: RunDistinction | null;
    /**
     * What tells this run apart from the other listed runs of its algorithm that go by the same
     * name: the names of the parameters whose values differ, sorted, or an empty list when only
     * the scope differs. Null while no other run shares the name.
     * @since 3.18.0
     */
    readonly siblingsDifferBy: readonly string[] | null;

    /** Which algorithm ran. */
    readonly algorithm: AlgorithmKey;
    /** The parameters it ran with, canonicalised. */
    readonly params: Readonly<Record<string, unknown>>;
    /** The seed it used, or null when it needed none. */
    readonly seed: number | null;
    /** The scope it ran over. */
    readonly scope: RunScopeRecord;
    /** Where the run got to. */
    readonly status: RunStatus;
    /** When it started, as an ISO 8601 timestamp, or null while it is still queued. */
    readonly startedAt: string | null;
    /** How long it took, in milliseconds, or null until it finishes. */
    readonly durationMs: number | null;
    /** Whether it stopped early and published what it had: true exactly when `caveats.partialReason` is set. */
    readonly partial: boolean;
    /** Why its numbers no longer describe what is on screen, when they do not. */
    readonly stale: StaleNote | null;
    /** Which versions produced the numbers. */
    readonly engine: EngineVersions;
    /** The fields the run published. */
    readonly fields: readonly FieldDescriptor[];
    /** The shape, which fixes those field names. */
    readonly shape: ResultShape;
    /** What qualifies the numbers. */
    readonly caveats: Caveats;
    /** The bounded form of the result, once there is one. */
    readonly summary?: ResultSummary;
}

/**
 * A started computation.
 *
 * A run is a `PromiseLike`, NOT a `Promise` subclass, and the element attaches a no-op rejection
 * handler to the promise behind it. The two together are what make an element driven by clicks,
 * a console and an agent safe to use: a run fired from a click handler and never awaited cannot
 * produce an unhandled rejection, while `await run` still throws. Subclassing `Promise` would
 * give the opposite -- every unawaited failure reaching the window as an unhandled rejection --
 * and there is no way to have both.
 *
 * What a rejection means is fixed, so a consumer can tell the three cases apart without parsing
 * a message:
 *
 * - `cancel()` and an aborted `signal` reject with a `DOMException` named `AbortError`, which is
 *   what every consumer already knows how to test for.
 * - `AbortSignal.timeout()` rejects with a `DOMException` named `TimeoutError`, so a timeout is
 *   distinguishable from somebody pressing Cancel.
 * - Everything else rejects with a {@link GraphtyError} carrying a code.
 *
 * A time boxed run that hits its box does not reject at all: it RESOLVES, with `partial` set and
 * `caveats.partialCause` saying why. A stopped-early result is data.
 */
export interface Run<T = RunResult> extends PromiseLike<T> {
    /** The run id: stable, selector-safe, and author-assignable through `as`. */
    readonly id: RunId;
    /**
     * What to call the run.
     *
     * Computed by the element, never by the consumer: the algorithm's plain name on its own
     * while it is the only run of that algorithm, gaining the parameter that differs in
     * parentheses the moment a sibling exists. One string, used by the layer row, the legend,
     * the journal and every export.
     * @deprecated Word the run from its `algorithm`, {@link Run.distinguishedBy} and
     *   {@link Run.siblingsDifferBy} yourself. Removed in the next major.
     */
    readonly label: string;
    /**
     * The option this run's name was suggested by, once it left its default: what tells it apart
     * from a run of the same algorithm at the defaults. Null for a run at the defaults, a run the
     * caller named with `as`, a batch, and a run of an algorithm registered with its own
     * `suggestedName`.
     * @since 3.18.0
     */
    readonly distinguishedBy: RunDistinction | null;
    /**
     * What tells this run apart from the other listed runs of its algorithm that go by the same
     * name: the names of the parameters whose values differ, sorted, or an empty list when only
     * the scope differs. Null while no other run shares the name.
     * @since 3.18.0
     */
    readonly siblingsDifferBy: readonly string[] | null;

    /** Which algorithm is running. */
    readonly algorithm: AlgorithmKey;
    /** The parameters it is running with, canonicalised. */
    readonly params: Readonly<Record<string, unknown>>;
    /** What it is allowed to look at, resolved against the graph as it stood when it started. */
    readonly scope: ResolvedScope;
    /** Where it has got to. */
    readonly status: RunStatus;
    /** How far along it is. */
    readonly progress: Progress;
    /** Whether the total is knowable, so a consumer can choose a bar or a spinner. */
    readonly determinate: boolean;
    /** Whether it can be stopped. Distinct from whether it HAS been stopped. */
    readonly cancellable: boolean;
    /** Its place in the queue, counting from 0, or null when it is not waiting. */
    readonly queuePosition: number | null;
    /** When it started, as an ISO 8601 timestamp, or null while it is still queued. */
    readonly startedAt: string | null;
    /** How long it took, in milliseconds, or null until it finishes. */
    readonly durationMs: number | null;
    /**
     * Whether it stopped early and published what it had. Not a failure. True exactly when
     * `caveats.partialReason` is set, whatever stopped it -- a time box or an iteration cap.
     */
    readonly partial: boolean;
    /** Why its numbers no longer describe what is on screen, when they do not. */
    readonly stale: StaleNote | null;
    /** Which versions produced the numbers. */
    readonly engine: EngineVersions;
    /** The fields it publishes. */
    readonly fields: readonly FieldDescriptor[];
    /** The shape, which fixes those field names. */
    readonly shape: ResultShape;
    /** What qualifies the numbers. */
    readonly caveats: Caveats;
    /**
     * The result, once there is one. Awaiting the run is the other way to get it. Undefined
     * again once undo has taken the run out of the project (`status` "removed"); a redo brings the
     * same result object back.
     *
     * Spelled `?: T | undefined` rather than `?: T` because the implementation answers with a
     * getter, and under a consumer's `exactOptionalPropertyTypes` a getter that can return
     * undefined does not satisfy a property that can only be absent or present.
     */
    readonly result?: T | undefined;
    /** Why it failed, when it failed. Optional-or-undefined for the reason {@link Run.result} gives. */
    readonly error?: GraphtyError | undefined;
    /** The frozen, structured-cloneable snapshot of everything above. */
    readonly record: RunRecord;
    /**
     * The journal entry this run's command wrote (`session.journal.get(run.journalId)`), or null
     * until the command has finished. A re-run points it at the newer entry.
     */
    readonly journalId: JournalId | null;
    /**
     * Stop the run.
     *
     * The promise rejects with a `DOMException` named `AbortError`. Calling this on a run that
     * has already finished does nothing.
     * @param reason - Why, for the journal and for an error message.
     */
    cancel(reason?: string): void;
    /**
     * Run it again, in place.
     *
     * The new run keeps the SAME id, so every style layer, legend and saved reference bound to
     * it survives. That is what "re-run from a layer" needs, and it is why a binding never
     * dangles after a re-run. The last result stays readable until the new one is recorded, and
     * undoing the re-run puts the previous result back without computing it again.
     * @returns The run, which is this one restarted rather than a second entry.
     */
    rerun(): Run<T>;
    /**
     * What this run suggests be drawn from it.
     *
     * Derived from the run's own shape and the fields it published, never from a block of styling
     * written per algorithm: a measurement suggests a colour over the elements it measured, a
     * grouping suggests a categorical colour, a route or a chosen set suggests a mark, and a
     * table of pairs, a time series or a bare fact suggests nothing at all.
     *
     * The element applies these itself on a run's first completion unless `{ style: false }` was
     * asked for. Reading them is for a consumer that wants to show what WOULD be painted, apply it
     * at another moment, or alter the taste before it lands -- each suggestion is the specification
     * `styles.encode()` or `styles.mark()` takes; an encoding leaves its taste unsaid so the
     * element's own defaults settle it, and a mark carries the channel values it paints.
     * @returns The suggestions, empty when the result is read rather than painted.
     */
    suggestEncodings(): readonly StyleSuggestion[];
}

// ---------------------------------------------------------------------------------------------
// The runs API
// ---------------------------------------------------------------------------------------------

/** One waiting run's place in the queue. */
export interface QueueEntry {
    /** The run that is waiting. */
    readonly runId: RunId;
    /** Its position, counting from 0. */
    readonly index: number;
    /** How many runs are waiting in total, so a consumer can say "2 of 3". */
    readonly of: number;
}

/**
 * What removing a run took with it.
 *
 * Returned so a consumer can say "Removes 1 style layer" BEFORE it asks for confirmation, which
 * is the difference between a delete a reader can consent to and one they discover afterwards.
 */
export interface RunRemoval {
    /** How many style layers were removed with the run. */
    readonly removedLayers: number;
    /** Which ones, so an undo can name them. */
    readonly layerIds: readonly LayerId[];
}

/**
 * What became of one style suggestion a run made when it first completed.
 *
 * Branch on `outcome` and keep a default branch: more outcomes may be added in a minor release.
 * Ids only, never names, so a consumer looks a layer or run up live (`styles.get(id)`,
 * `runs.get(id)`) and words the result itself.
 */
export type SuggestionOutcome =
    | {
          /** The suggestion was added to the style stack. */
          readonly outcome: "added";
          readonly suggestion: StyleSuggestion;
          /** The layers it added: one for an encoding, one per half for a mark or a highlight. */
          readonly layerIds: readonly LayerId[];
          /**
           * Set when it was placed directly beneath a hand-written layer that drives one of its
           * channels on some elements, so that layer still shows there.
           */
          readonly placedBeneathLayerId?: LayerId;
      }
    | {
          /** Not added: a hand-written layer already drives this channel on every element. */
          readonly outcome: "suppressed";
          readonly suggestion: StyleSuggestion;
          /** That layer. */
          readonly byLayerId: LayerId;
      }
    | {
          /** Not added: a later member of the same batch suggested the same channel. */
          readonly outcome: "superseded";
          readonly suggestion: StyleSuggestion;
          /** The batch member whose suggestion for this channel was used instead. */
          readonly byRunId: RunId;
      }
    | {
          /** Not added: the style stack refused it. The same error went to `style:problem`. */
          readonly outcome: "refused";
          readonly suggestion: StyleSuggestion;
          /** The code of that error. */
          readonly code: GraphtyErrorCode;
      };

/**
 * What the element decided to paint for a run when it first completed.
 *
 * A snapshot of that one decision, kept with the run so undo and redo carry it. It does not track
 * later edits to the stack; `styles.legend()` and `styles.explain()` answer what shows now.
 */
export interface RunPainting {
    /**
     * Where the decision stands. More states may be added in a minor release.
     *
     * - `"decided"`: `suggestions` is the decision; empty when the run had nothing to draw.
     * - `"pending"`: the run has not finished, or it is a batch member and the batch has not.
     * - `"opted-out"`: started with `style: false`.
     * - `"not-succeeded"`: it failed or was cancelled.
     * - `"no-styles"`: this session has no style stack.
     * - `"unknown"`: the run was recorded without a decision, so none is known.
     */
    readonly state: "decided" | "pending" | "opted-out" | "not-succeeded" | "no-styles" | "unknown";
    /** One entry per suggestion; empty unless `state` is `"decided"`. */
    readonly suggestions: readonly SuggestionOutcome[];
}

/**
 * Starting runs, finding them, and taking them away.
 *
 * Starting the same algorithm with the same parameters over the same scope returns the run that
 * already exists rather than a second one, re-executing it in place if the data moved under it.
 * Ids are therefore deterministic -- derived from the algorithm, the canonical parameters and
 * the scope digest, never from an execution counter -- so that a saved layer, recipe or template
 * resolves to the same run whatever order things happened to run in.
 */
export interface RunsApi {
    /**
     * Start one algorithm.
     *
     * The scope is resolved when the call is made, and again when the work starts: a set it names
     * that is redefined while the run waits in the queue is run over as redefined, and the run
     * records the revision it used (`record.scope.set.revision`).
     * @param algorithm - Which algorithm to run.
     * @param params - Its parameters.
     * @param options - The scope, the seed, the id and the rest.
     * @returns The run, which is awaitable and watchable straight away.
     * @throws `E_SCOPE_EMPTY` when a scope other than `"graph"` or `"visible"` holds no nodes (a
     * run that finds it empty only when its work starts fails with the same code);
     * `E_BAD_COMMAND` for a malformed scope or a set id never issued.
     */
    start(algorithm: AlgorithmKey, params?: Readonly<Record<string, unknown>>, options?: StartOptions): Run;
    /**
     * The finished run `start()` with these arguments would hand back as it is, computing nothing:
     * the same question, asked with the same parameters and seed, answered over a scope and data
     * that have not moved since. Undefined when `start()` would compute -- the first time, after
     * the parameters, the scope or the data changed, or after the run failed -- so a control that
     * starts a run can tell beforehand whether pressing it would change anything.
     *
     * Whether `start()` would put back layers the reader deleted is a separate fact:
     * {@link RunsApi.layers}.
     * @param algorithm - Which algorithm.
     * @param params - Its parameters.
     * @param options - The scope, the seed, the id and the rest, as `start()` takes them.
     * @returns The run, or undefined.
     * @since 3.33.0
     */
    answered(
        algorithm: AlgorithmKey,
        params?: Readonly<Record<string, unknown>>,
        options?: StartOptions,
    ): Run | undefined;
    /**
     * Start several algorithms as one piece of work, with one progress stream and one cancel.
     * @param specs - What to run.
     * @param options - The batch's label, and the ordinary run options.
     * @returns A run over the batch, resolving to how each member turned out.
     */
    batch(specs: readonly RunSpec[], options?: RunOptions & { readonly label?: string }): Run<BatchResult>;
    /**
     * One run, by id.
     * @param id - The run id.
     * @returns The run, or undefined when this session holds none with that id.
     */
    get(id: RunId): Run | undefined;
    /**
     * Every run this session holds, finished or not.
     * @returns The runs, in the order they were started.
     */
    list(): readonly Run[];
    /**
     * Remove a run and every style layer reading it.
     *
     * This is the other delete verb: removing a LAYER takes away the picture and keeps the
     * result, removing a RUN takes away the result and everything drawn from it.
     * @param id - The run id.
     * @returns What went with it.
     */
    remove(id: RunId): RunRemoval;
    /**
     * Move every style layer reading a run, as one block and in its own order, to another place
     * in the stack, as one step.
     *
     * `before` reads as it does in `styles.move`: the block sits IMMEDIATELY BELOW that layer,
     * and `null` means the top of the stack. A run that no layer reads moves nothing.
     * @param id - The run id.
     * @param before - The layer to sit below, or null for the top of the stack.
     * @param options - How the move is dispatched.
     * @param options.signal - Withdraws the move.
     * @returns Settles once the block has moved. Rejects with `E_UNKNOWN_RUN` for a run this
     *     session does not hold, `E_UNKNOWN_LAYER` when `before` is not in the stack,
     *     `E_PROTECTED` when `before` is an element-owned layer (nothing goes beneath those) and
     *     `E_BAD_COMMAND` when `before` is one of the run's own layers.
     */
    move(id: RunId, before: LayerId | null, options?: { readonly signal?: AbortSignal }): Promise<void>;
    /**
     * Which style layers read a run.
     *
     * Run-to-layer is many-to-many, so a layer reading two runs survives the removal of one.
     * @param id - The run id.
     * @returns The layer ids.
     */
    bindings(id: RunId): readonly LayerId[];
    /**
     * What the element decided to paint when a run first completed: one outcome per style
     * suggestion the run made.
     *
     * Readable as soon as `await run` returns. A re-run keeps the first decision, because a
     * re-run does not repaint. `"added"` means the layers went on the stack, not that they show:
     * a layer added later may cover it, which `styles.legend()` shows.
     * @param id - The run id.
     * @returns The decision, or undefined when this session holds no run with that id.
     */
    painting(id: RunId): RunPainting | undefined;
    /**
     * Which of a run's layers the stack holds, and which of those it added on its first
     * completion are gone: what decides between "update the layer" and "add the layer back" before
     * a reader starts the run again.
     * @param id - The run id.
     * @returns The layers, or undefined when this session holds no run with that id.
     * @since 3.26.0
     */
    layers(id: RunId): RunLayers | undefined;
    /** The runs waiting to start, in queue order. */
    readonly queue: readonly QueueEntry[];
}
