/**
 * @file The legend: what a reader is told about the picture, derived from the encoding model and
 * never from the canvas.
 *
 * THE SOURCE IS THE MODEL, WHICH IS WHY THIS FILE IS HEADLESS. A legend built by sampling pixels
 * can only describe the frame that happened to be on screen: it cannot be asserted in a Node
 * test, it cannot be composed into an export at four times the screen's scale, and it goes stale
 * the moment the camera moves. Every block below is read out of the prepared bindings the repaint
 * already painted from, so the legend and the picture are two readings of one object rather than
 * two guesses that have to be kept in step.
 *
 * DEPARTURES ARE THE HONEST PART. A colour ramp that quietly clamps at the 2nd and 98th
 * percentiles, a logarithmic scale with 312 zeros it cannot plot, a run that measured 300 nodes
 * of 50,000 -- each of those makes the picture say something narrower than "this is the data",
 * and a legend that prints the ramp without printing the narrowing is the thing that turns a
 * reasonable choice into a false claim. {@link LegendBlock.facts} carries them as coded facts
 * (`{ code, params }`) for the application to word, most of them straight off the prepared
 * binding, which counted them while it was settling the domain and therefore pays nothing extra
 * to report them.
 *
 * ONE DEPARTURE IS THIS FILE'S OWN. A layer lower in the stack can be painted over by a layer
 * above it that writes the same channel over EVERY element, and a block describing colours no
 * reader can see is exactly the false claim the rest of the list exists to prevent. The stack is
 * right here, so it is checked and said.
 *
 * WHAT THE BLOCKS ARE IN: the same order {@link import("./StylesApi").StylesApi.list} returns,
 * BOTTOM FIRST. A second reading order for the same stack is how an off-by-one gets in, and a
 * consumer that wants the winning layer first reverses a list it already draws bottom first.
 *
 * THE WORDS ARE THE APPLICATION'S. A block names its field by path, its scale by id and each row
 * by its value, and every departure is a code with its numbers and names as parameters. The
 * English fields that remain (`label`, `plainName`, the scale's `label`, `departures`) are
 * deprecated and kept only until the next major:
 *
 * - A scale's deprecated words are its catalogue entry's `plainName`.
 * - A field's deprecated words come from whoever holds the session's attributes and run fields,
 *   through {@link LegendSources.field}. Absent, the path's last segment is humanised.
 *
 * Nothing here reaches Babylon.js, Lit or the DOM.
 */

import type { AlgorithmKey, Binding, Channel, LayerId, PaletteId, Path, RunId } from "../../catalog/types";
import { groupName, RESULT_ROOT } from "../results/types";
import type { CodedFact } from "../shared";
import type { EncodedValue, PreparedBinding } from "./encoding";
import type { Layer } from "./Layer";
import type { SelectorTarget } from "./predicate";
import type { ScaleRegistry } from "./scales";

// ---------------------------------------------------------------------------------------------
// What a legend is made of
// ---------------------------------------------------------------------------------------------

/**
 * One row of a legend: a value, and what the picture paints for it.
 *
 * `value` is the DATA value -- the category, or a number on the domain -- and `color`, `size` and
 * `paints` are what the encoding turns it into. Word a row from its facts: `value`, `extent`,
 * `rank`, and `role` with `count`.
 */
export interface LegendSwatch {
    /**
     * The value in English words.
     * @deprecated Word the row yourself from its facts: `value` (and `extent` for a row covering a
     *   range of numbers), `rank` for a run's group, `role: "other"` with `count` for the folded
     *   bucket, and the layer's own `name` (from `styles.get(layerId)`) for a fixed value. Removed
     *   in the next major.
     */
    readonly label: string;
    /**
     * The value itself, for a consumer that wants to filter or select by it -- spelled as the data
     * spells it, so a run's group `0` is the number `0` here as it is in the run's summary, its
     * `sizes` table and its per-node values, never the string `"0"`.
     */
    readonly value: unknown;
    /**
     * The lowest and highest values this row stands for, on a row of an encoding that cuts a
     * numeric domain into groups (`value` is `extent.min`). Absent on any other row.
     * @since 3.16.0
     */
    readonly extent?: {
        /** The lowest value painted like this row. */
        readonly min: number;
        /** The highest value painted like this row. */
        readonly max: number;
    };
    /**
     * The group's place by size, from 1 for the largest, on a block that colours a run's groups
     * (`results.<run>.group`): the same `rank` the run summary's group carries, so a list of
     * groups, a table column and the legend can name one group the same way. Absent on any other
     * row.
     */
    readonly rank?: number;
    /**
     * The binding does not paint this value (its `hidden` list names it): elements carrying it
     * are drawn as the layers beneath paint them. `color`, `size` and `paints` still say what the
     * value is painted when it is shown again. Absent on a row that is painted.
     */
    readonly hidden?: true;
    /**
     * The name a reader gave this value (`session.data.setValueLabel`). Absent when it has none.
     * @since 3.26.0
     */
    readonly name?: string;
    /**
     * The value is an arbitrary code the element made up (a run's group id), not something the
     * data says: an application names it ("Group 3", by `rank`) until a reader names it. Absent on
     * a value the data supplied.
     * @since 3.26.0
     */
    readonly arbitrary?: true;
    /** The colour the encoding paints it, as `#rrggbb` or `#rrggbbaa`. */
    readonly color?: string;
    /** The size or width the encoding paints it. */
    readonly size?: number;
    /** How many elements carry it, when whoever supplied the encoding can say. Always set on the `"other"` row. */
    readonly count?: number;
    /**
     * What the encoding paints it when that is neither a colour nor a size -- a node shape, a
     * line pattern, an arrow.
     *
     * Those channels carry one of a fixed list, and a list of names has no chip a `color` or a
     * `size` could stand in for. Without this a legend for "shape by community" could name the
     * communities and not the shapes, which is half a legend.
     */
    readonly paints?: unknown;
    /**
     * What the row stands for. `"other"` marks the one bucket the paint folded the smaller groups
     * into: its `value` lists the values it holds and its `count` how many elements carry them,
     * and it is always the last row, kept even when the rows above it are capped.
     *
     * OPEN UNION: roles may be added in a minor release. Absent on an ordinary row.
     */
    readonly role?: "other" | (string & {}); // NOSONAR(S4335): the open-union idiom; keeps the known literals in autocomplete while accepting others
    /**
     * A layer above paints the block's channel on every element the block's layer selects that
     * carries this value, so none of them shows this row's paint: the layer shown on the most of
     * them. Absent while at least one element carrying the value shows it, and on a row no element
     * carries. Set on the rows of a categorical block only.
     * @since 3.33.0
     */
    readonly paintedOverBy?: LayerId;
}

/**
 * What a higher value means on the drawing, as a fact for a legend to put in its own words.
 *
 * `code` names the fact and `params` carries its parts, so an application writes the sentence
 * ("Darker means more Influence", with the field's words from {@link LegendBlock.field}) in its
 * own language and voice.
 */
export interface LegendReading {
    /** A higher value of `field` is drawn further in `direction` on `channel`. */
    readonly code: "legend.higher";
    /** The parts of the fact. */
    readonly params: {
        /** The channel the block describes. */
        readonly channel: Channel;
        /**
         * Which way a higher value moves the paint: `"darker"` or `"lighter"` for a colour (by
         * the luminance of the colours painted at the two ends of the domain), `"larger"` or
         * `"smaller"` for a number such as a size, a width or an opacity.
         */
        readonly direction: "darker" | "lighter" | "larger" | "smaller";
        /** The column path the encoding reads. */
        readonly field: Path;
    };
}

/**
 * Everything a reader is told about one channel of one layer.
 *
 * `field`, `scale`, `domain` and `palette` are each absent when there is nothing true to put in
 * them: a layer that writes a fixed colour reads no field, passes through no scale and has no
 * domain, and the prepared binding says so by carrying a null path and a null scale. Filling them
 * with a placeholder would put a field name in a legend that names no field.
 */
export interface LegendBlock {
    /** The channel the block describes. */
    readonly channel: Channel;
    /**
     * The layer that paints it. For a block standing for several copies (`layers`), the copy
     * shown on the most elements, whose domain and swatches the block reads.
     */
    readonly layerId: LayerId;
    /**
     * Every layer whose copy of the same binding this one block stands for, bottom first, when
     * several layers hold an identical binding (a binding copied into each of a folder's layers):
     * {@link StylesApi.legend} lists such copies once. Absent for a block of one layer.
     * @since 3.29.0
     */
    readonly layers?: readonly LayerId[];
    /** The run behind the layer, when a run put it there. */
    readonly runId?: RunId;
    /** What shape of legend a consumer draws: a ramp, a list of colours, a single chip. */
    readonly kind: "sequential" | "diverging" | "categorical" | "highlight" | "literal";
    /** The field the encoding reads. `path` is the id to word it by. */
    readonly field?: {
        /**
         * The field's name in English.
         * @deprecated Word the field yourself from `path` (for example by looking it up in
         *   `session.data.attributes()` or the run's fields). Removed in the next major.
         */
        readonly plainName: string;
        /** The name the literature and the data use. */
        readonly technicalName: string;
        /** The column path itself. For a data column it is the `path` of its entry in `session.data.attributes()`. */
        readonly path: Path;
        /**
         * For a field a run published: the algorithm's catalog key and the field's `name` among
         * that algorithm's `fields`, so the field is found in the catalog by id. Absent for a data
         * column, and for a path no run in the session publishes.
         * @since 3.16.0
         */
        readonly result?: FieldResult;
    };
    /** The scale the values pass through. */
    readonly scale?: {
        /** The scale's id, which is what a binding spells (`"linear"`, `"log"`, `"sqrt"`, ...). */
        readonly kind: string;
        /**
         * The same scale in English words, from the scale catalogue.
         * @deprecated Word the scale yourself from `kind`. Removed in the next major.
         */
        readonly label: string;
    };
    /** The extent values were read against, and how it was narrowed. */
    readonly domain?: {
        /** The low end. */
        readonly min: number;
        /** The high end. */
        readonly max: number;
        /** The value a diverging palette centres on, when the binding named one. */
        readonly midpoint?: number;
        /** The percentiles the extent was cut at, when the binding asked for a clamp. */
        readonly clamped?: {
            /** The low percentile, such as "p2". */
            readonly from: string;
            /** The high percentile, such as "p98". */
            readonly to: string;
        };
    };
    /**
     * What a higher value means on the drawing. Present only for an encoding that reads a numeric
     * domain and paints its two ends differently in one direction: absent for categories, for a
     * diverging palette (both ends are strong), for a fixed value and for a domain of one value.
     * @since 3.10.0
     */
    readonly reading?: LegendReading;
    /**
     * The range the binding maps values onto, in the channel's own units ("1 to 3" for a node
     * size; node size is unitless, never pixels). Present only for a channel that carries a
     * number, such as `node.size` or `edge.width`, and absent when the binding's `map` or `other` paints values
     * of its own, which the range does not bound. It is the binding's range, not the smallest and
     * largest swatch: a reversed binding still reads low to high here, and the swatches are only
     * samples of it.
     * @since 3.10.0
     */
    readonly range?: {
        /** The low end. */
        readonly min: number;
        /** The high end. */
        readonly max: number;
    };
    /** The palette, when the channel carries a colour. */
    readonly palette?: {
        /** The palette's id. */
        readonly name: PaletteId;
        /** Whether the smallest value lands at the far end of it. */
        readonly reversed: boolean;
    };
    /** Up to twelve rows, plus the `"other"` row when the paint folded some groups. */
    readonly swatches: readonly LegendSwatch[];
    /**
     * How many elements this block's layer currently paints on this channel: the elements where
     * it is the layer the picture shows, as `styles.counts(layerId).painted[channel]` counts them.
     * 0 when the layer matches nothing right now (a Selected row with nothing selected) or a layer
     * above paints over all of it, so a consumer can leave such a block out.
     * @since 3.26.0
     */
    readonly painted?: number;
    /**
     * How many elements of its kind the block's layer selects among those drawn (`count`) out of
     * how many the graph holds (`of`), present when that is fewer than all of them: a layer of
     * hand-picked nodes, one narrowed by a condition, or one whose elements a visibility step hides.
     * An element a filter step hides is not counted, so `count` is 0 for a layer whose every
     * element is hidden, and a consumer can leave such a block out. A block standing for several
     * copies (`layers`) counts what the copies select together. Absent for a layer whose selector
     * is `everything`.
     * @since 3.33.0
     */
    readonly scope?: {
        /** How many of the elements drawn the layer selects. */
        readonly count: number;
        /** How many elements of that kind the graph holds. */
        readonly of: number;
    };
    /** How many rows did not fit, when some did not. The `"other"` row is never counted here. */
    readonly overflow?: {
        /** How many rows were left out of `swatches`, as a number. */
        readonly hidden: number;
    };
    /**
     * What this encoding does that the picture alone does not admit to, one fact per departure, in
     * the order a legend reads them. Empty when the encoding has nothing to confess.
     * @since 3.16.0
     */
    readonly facts: readonly LegendFact[];
    /**
     * The same departures as English sentences.
     * @deprecated Word {@link LegendBlock.facts} yourself. Removed in the next major.
     */
    readonly departures: readonly string[];
}

/**
 * What a legend fact says. Each code carries these `params`:
 *
 * - `legend.clamped` -- the extent was cut at percentiles: `{ from, to }`, the two percentiles
 *   (for example `2` and `98`).
 * - `legend.not-plottable` -- some values have no place on the scale and are not painted:
 *   `{ count, scale }`, how many, and the scale's id (a zero under `"log"`, for instance).
 * - `legend.none-plottable` -- no value has a place on the scale: `{ scale }`.
 * - `legend.no-value-in-domain` -- the binding's explicit domain has no place on its scale:
 *   `{ min, max }`, the domain as written.
 * - `legend.nothing-measured` -- the column held no value to read: `{}`.
 * - `legend.unreadable` -- values the scale cannot read (text under a numeric scale): `{ count }`.
 * - `legend.lumped` -- values folded into the `"other"` row: `{ count }`, how many elements.
 * - `legend.not-measured` -- elements in scope the run measured nothing for: `{ count }`.
 * - `legend.painted-over` -- a layer above paints the same channel over every element this one
 *   reaches, so none of this block is visible: `{ layerId, name }`, that layer's id and name.
 * @since 3.16.0
 */
export type LegendFactCode =
    | "legend.clamped"
    | "legend.not-plottable"
    | "legend.none-plottable"
    | "legend.no-value-in-domain"
    | "legend.nothing-measured"
    | "legend.unreadable"
    | "legend.lumped"
    | "legend.not-measured"
    | "legend.painted-over";

/**
 * One departure of a legend block, as a code and the values it is about.
 * @since 3.16.0
 */
export type LegendFact = CodedFact<LegendFactCode>;

/**
 * Which run field a legend field is: the algorithm's catalog key and the field's `name`.
 * @since 3.16.0
 */
export interface FieldResult {
    /** The catalog key of the algorithm that published it, as `BUILT_IN_ALGORITHMS` spells it. */
    readonly algorithm: AlgorithmKey;
    /** The field's `name` in that algorithm's `fields`. */
    readonly field: string;
}

/** The words one field goes by. */
export interface FieldWords {
    /** The name a reader sees. */
    readonly plainName: string;
    /** The name the literature and the data use. */
    readonly technicalName: string;
    /**
     * Which run field it is, when a run published it.
     * @since 3.16.0
     */
    readonly result?: FieldResult;
}

/**
 * How the encodings one layer prepared are looked up.
 *
 * The legend and the explanation both read the SAME prepared bindings the repaint painted from.
 * Preparing a second set here would walk every bound column again -- 3.3 to 4.6 ms per continuous
 * binding at fifty thousand values -- to produce an answer that would disagree with the picture
 * the moment the data moved.
 *
 * A LIST RATHER THAN A LOOKUP BY CHANNEL, in the order the repaint applies them, because that is
 * the shape the repaint already holds: a layer's prepared channels are a list, and handing one
 * over needs no index keyed by something else. Every binding names the channel it paints, so
 * nothing is lost, and the order is the paint order rather than an order invented here.
 * @param layerId - The layer.
 * @returns Its prepared bindings, fixed values first and rules second. Empty for a layer that
 *   paints nothing, and for one the repaint could not prepare at all.
 */
export type EncodingLookup = (layerId: LayerId) => readonly PreparedBinding[];

/** Everything a legend is built from. */
export interface LegendSources {
    /**
     * The stack, BOTTOM FIRST, exactly as `styles.list()` returns it.
     * @returns The layers.
     */
    layers(): readonly Layer[];
    /** Where the prepared encodings are read from. */
    readonly encoding: EncodingLookup;
    /** The session's scales, for the words a scale goes by. */
    readonly scales: ScaleRegistry;
    /**
     * The words one field goes by, from the session's attributes and run fields.
     *
     * Absent, or absent for a particular path, the path's last segment is humanised.
     * @param path - The column path.
     * @param target - Whether the layer asking paints nodes or edges.
     * @returns The words, or undefined when nothing in the session names that path.
     */
    readonly field?: (path: Path, target: SelectorTarget) => FieldWords | undefined;
    /**
     * Whether a layer above selects every element a layer below it selects.
     *
     * Absent, only a layer that selects everything is known to cover one below it.
     * @param above - The higher layer.
     * @param below - The lower layer.
     * @returns True only when every element `below` selects is also selected by `above`.
     */
    readonly covers?: (above: Layer, below: Layer) => boolean;
    /**
     * Each group's place by size in one run, from its `sizes` table, keyed by the group as a
     * category name: the rank the run summary and the page columns carry.
     *
     * Absent, or undefined for a run, a swatch's rank is its place among the swatches.
     * @param runId - The run.
     * @returns The rank by group, or undefined when the run has no sizes table.
     */
    readonly groupRanks?: (runId: string) => ReadonlyMap<string, number> | undefined;
    /**
     * The names given to one path's values (`data.setValueLabel`), by the value as the legend
     * spells it. Absent, no swatch carries a name.
     * @param path - The value path.
     * @returns The names.
     */
    readonly valueLabels?: (path: Path) => ReadonlyMap<string, string>;
    /**
     * How many elements one layer is the shown layer on, per channel it writes.
     *
     * Absent, the blocks carry no `painted` count.
     * @param layerId - The layer.
     * @returns The count per channel.
     */
    readonly painted?: (layerId: LayerId) => Readonly<Partial<Record<Channel, number>>>;
    /**
     * Whether a layer is the base look's home (the Everything row while `editableBase` is on):
     * its plain values are what the picture looks like when nothing has been said about the data,
     * as a base layer's are, so only what it reads from the data is listed.
     *
     * Absent, no layer is.
     * @param layer - The layer.
     * @returns True for the base look's home.
     */
    readonly holdsBase?: (layer: Layer) => boolean;
    /**
     * The categories one layer's binding for a channel meets among the elements the layer
     * selects, spelled as the legend spells a category. Read only for copies of one binding the
     * legend folds into one block, so the block lists what the copies paint and no more.
     *
     * Absent, a folded block keeps its first copy's rows.
     * @param layerId - The layer.
     * @param channel - The channel.
     * @returns The categories, or undefined when the layer binds no category there.
     */
    readonly reached?: (layerId: LayerId, channel: Channel) => ReadonlySet<string> | undefined;
    /**
     * How many of the elements drawn one layer selects, and how many of its kind the graph holds.
     * Read only for a layer whose selector is not `everything`.
     *
     * Absent, no block carries a `scope`.
     * @param layerId - The layer.
     * @returns The two counts.
     */
    readonly selects?: (layerId: LayerId) => { readonly count: number; readonly of: number };
    /**
     * For each category one layer's binding meets among the elements it selects, how many carry
     * it, how many of those show the layer's paint for the channel, and the layer shown instead on
     * the most of the rest. Read for a categorical block only.
     *
     * Absent, no swatch carries `paintedOverBy`.
     * @param layerId - The layer.
     * @param channel - The channel.
     * @returns The reach by category, or undefined when the layer binds no category there.
     */
    readonly reach?: (layerId: LayerId, channel: Channel) => ReadonlyMap<string, ValueReach> | undefined;
}

/** What one category of a layer's binding reaches; see {@link LegendSources.reach}. */
export interface ValueReach {
    /** How many elements the layer selects that carry the category. */
    readonly carried: number;
    /** How many of those show the layer's paint for the channel. */
    readonly shown: number;
    /** The layer the picture shows instead on the most of the rest, when any. */
    readonly coveredBy?: LayerId;
}

// ---------------------------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------------------------

/** How many swatches a block carries at most, whatever the encoding has to show. */
const SWATCH_CAP = 12;

/**
 * How many stops a continuous ramp is sampled at.
 *
 * Odd, so that the middle of the domain -- which is what a diverging palette centres on -- is one
 * of the stops rather than a gap between two of them.
 */
const RAMP_STOPS = 7;

/**
 * The fewest samples a stepped numeric encoding is swept with, and the fewest per group.
 *
 * The cut points of a grouping by equal counts are a property of the column, and a prepared
 * binding does not publish them; nor does a plugin's scale publish anything at all. Sweeping the
 * domain and watching for the painted value to change finds the boundaries of ANY scale from the
 * outside, at about 12 ns a sample, which is three microseconds for the whole sweep.
 *
 * The per-group floor is what keeps the count EXACT rather than merely plausible: a fixed sample
 * count would start merging neighbouring groups once there were more groups than samples, and an
 * overflow that says "and 6 more" when there are nine is the kind of quiet wrongness a legend
 * exists to prevent.
 */
const SWEEP_SAMPLES = 256;

/** How many samples every group of a stepped encoding gets at least. */
const SWEEP_PER_GROUP = 8;

/** The blocks of a stack with nothing to say. */
const NO_BLOCKS: readonly LegendBlock[] = Object.freeze([]);

// ---------------------------------------------------------------------------------------------
// Words and numbers
// ---------------------------------------------------------------------------------------------

/**
 * Write a number the way a legend prints it.
 *
 * Four significant figures and then the trailing zeros taken off, so a domain that arrived as
 * 0.30000000000000004 reads as 0.3 and one that arrived as 1234567 does not become 1.235e+6 for
 * no reason.
 * @param value - The number.
 * @returns The number in the words a reader sees.
 */
function formatNumber(value: number): string {
    if (!Number.isFinite(value)) {
        return String(value);
    }

    if (Number.isInteger(value) && Math.abs(value) < 1e7) {
        return String(value);
    }

    const magnitude = Math.abs(value);
    if (magnitude >= 1e7 || (magnitude > 0 && magnitude < 1e-3)) {
        return value.toExponential(2);
    }

    return String(Number(value.toPrecision(4)));
}

/**
 * Turn a path into the words a field goes by when nothing in the session can name it.
 *
 * The last segment only: `results.betweenness-1.value` is a field called "Value" on a run, and
 * repeating the run id in the field's name says nothing the block's own `runId` does not.
 * @param path - The column path.
 * @returns The words, which are a fallback and not a lookup.
 */
function humanisePath(path: Path): FieldWords {
    const segments = path.split(".");
    const last = segments.at(-1) ?? path;
    const words = last
        .replaceAll(/([a-z\d])([A-Z])/g, "$1 $2")
        .split(/[\s_-]+/u)
        .filter((word) => word !== "");
    const plainName = words.map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");

    return { plainName: plainName === "" ? path : plainName, technicalName: path };
}

/**
 * The words one field goes by.
 * @param path - The column path.
 * @param target - Whether the layer paints nodes or edges.
 * @param sources - Where the session's own names are looked up.
 * @returns The words, from the session when it has them and from the path when it does not.
 */
function fieldWords(path: Path, target: SelectorTarget, sources: LegendSources): FieldWords {
    return sources.field?.(path, target) ?? humanisePath(path);
}

// ---------------------------------------------------------------------------------------------
// Reading a painted value
// ---------------------------------------------------------------------------------------------

/**
 * Whether a painted value is a colour.
 * @param value - What the encoding painted.
 * @returns True when it carries a hex string, which every colour channel's value does.
 */
function isColorValue(value: unknown): value is { hex: string } {
    return typeof value === "object" && value !== null && "hex" in value && typeof value.hex === "string";
}

/**
 * Split a painted value into the fields a swatch carries it in.
 * @param painted - What the encoding painted, or undefined when it paints this value nothing.
 * @returns The colour, the size, or the finished value of a channel that carries neither.
 */
function swatchPaint(painted: EncodedValue | undefined): Pick<LegendSwatch, "color" | "paints" | "size"> {
    if (painted === undefined) {
        return {};
    }

    if (isColorValue(painted)) {
        return { color: painted.hex };
    }

    if (typeof painted === "number") {
        return { size: painted };
    }

    return { paints: painted };
}

/**
 * A key two painted values are the same under.
 *
 * Colours are compared by their hex rather than by identity: the ramp mints a new object per
 * sampled step, so two samples of one colour are two objects and `===` would find every sweep
 * sample distinct.
 * @param painted - What the encoding painted.
 * @returns The key, or null when nothing was painted at all.
 */
function paintKey(painted: EncodedValue | undefined): string | null {
    if (painted === undefined) {
        return null;
    }

    if (isColorValue(painted)) {
        return painted.hex;
    }

    return typeof painted === "object" ? JSON.stringify(painted) : String(painted);
}

// ---------------------------------------------------------------------------------------------
// The swatches
// ---------------------------------------------------------------------------------------------

/** One run of domain values the encoding paints identically. */
interface PaintedRun {
    /** The lowest value in the run. */
    readonly from: number;
    /** The highest value in the run. */
    readonly to: number;
    /** What the encoding paints all of them. */
    readonly painted: EncodedValue;
}

/**
 * Sweep a numeric domain and collect the stretches the encoding paints identically.
 *
 * This is how a grouping by equal ranges, a grouping by equal counts and a plugin's scale nobody
 * here has heard of all produce correct group boundaries from the same code: the encoding is
 * asked, rather than reimplemented.
 * @param prepared - The prepared binding.
 * @param domain - The extent to sweep.
 * @returns The runs, in ascending order of value.
 */
function sweepRuns(prepared: PreparedBinding, domain: readonly [number, number]): readonly PaintedRun[] {
    const [low, high] = domain;
    const span = high - low;
    const samples = Math.max(SWEEP_SAMPLES, prepared.groups * SWEEP_PER_GROUP);
    const runs: PaintedRun[] = [];
    let key: string | null = null;

    for (let step = 0; step < samples; step++) {
        const value = span === 0 ? low : low + (span * step) / (samples - 1);
        const painted = prepared.paint(value);
        const sampleKey = paintKey(painted);

        if (sampleKey === null || painted === undefined) {
            key = null;
            continue;
        }

        const last = runs.at(-1);
        if (sampleKey === key && last !== undefined) {
            runs[runs.length - 1] = { from: last.from, to: value, painted: last.painted };
            continue;
        }

        key = sampleKey;
        runs.push({ from: value, to: value, painted });
    }

    return runs;
}

/**
 * The run whose groups a path reads.
 *
 * Those swatches are labelled with the names the run's summary gives the same groups, so a reader
 * sees "Group 1" in the key and in the list of groups rather than a raw id in one of them.
 * @param path - The column path.
 * @returns The run id for `results.<run>.group`, otherwise undefined.
 */
function groupsRunOf(path: Path | null): string | undefined {
    const parts = path?.split(".") ?? [];

    return parts.length === 3 && parts[0] === RESULT_ROOT && parts[2] === "group" ? parts[1] : undefined;
}

/**
 * The swatches of an encoding that names categories.
 * @param prepared - The prepared binding.
 * @param order - The values the binding maps, in the order it maps them: an ordinal column's
 *   declared order, which the rows follow before the rest.
 * @param sources - Where a run's group ranks come from.
 * @returns One swatch per category, largest group first, before the cap is applied.
 */
function categorySwatches(
    prepared: PreparedBinding,
    order: readonly string[],
    sources: LegendSources,
): readonly LegendSwatch[] {
    const run = groupsRunOf(prepared.path);
    const groups = run !== undefined;
    // The run's own ranks, so a group is ranked here as in its summary and its page column even
    // when an `order` re-sorts the rows or the layer's selector covers part of the run.
    const ranks = run === undefined ? undefined : sources.groupRanks?.(run);
    const rankOf = (category: string, index: number): number | undefined =>
        ranks === undefined ? index + 1 : ranks.get(category);
    const rank = (category: string): number => {
        const at = order.indexOf(category);
        return at === -1 ? order.length : at;
    };
    // A stable sort, so the categories no order names keep their largest-first order.
    const categories = [...prepared.categories].sort((left, right) => rank(left) - rank(right));
    const valueOf = (category: string): unknown => prepared.categoryValues.get(category) ?? category;
    const names = prepared.path === null ? undefined : sources.valueLabels?.(prepared.path);
    const row = (category: string, index: number): LegendSwatch => {
        const rank = groups ? rankOf(category, index) : undefined;
        const name = names?.get(category);
        return {
            label: name ?? (rank === undefined ? category : groupName(rank)),
            value: valueOf(category),
            ...(rank === undefined ? {} : { rank }),
            ...(name === undefined ? {} : { name }),
            // A run's group ids are made up by the run: a reader names them, never reads them.
            ...(groups ? { arbitrary: true as const } : {}),
            ...swatchPaint(prepared.paintIgnoringHidden(category)),
            ...(prepared.hidden.has(category) ? { hidden: true as const } : {}),
        };
    };
    const swatches: LegendSwatch[] = categories.map(row);
    const folded = prepared.lumped.length > 0 ? prepared.paintIgnoringHidden(prepared.lumped[0]) : undefined;

    if (folded === undefined) {
        return swatches;
    }

    // A hidden value the bucket folded is not painted, so it leaves the bucket's row for a row of
    // its own marked hidden, and the bucket's row says only what is still painted grey.
    const lumped = prepared.lumped.filter((category) => !prepared.hidden.has(category));
    for (const category of prepared.lumped) {
        if (prepared.hidden.has(category)) {
            swatches.push({ ...row(category, categories.length), ...swatchPaint(folded) });
        }
    }

    // The bucket gets one row saying what it holds, so a reader is told what the grey means
    // rather than left to guess. A binding that paints nothing for the bucket gets no row.
    if (lumped.length > 0) {
        const hiddenCount = prepared.lumped
            .filter((category) => prepared.hidden.has(category))
            .reduce((sum, category) => sum + (prepared.categoryCounts.get(category) ?? 0), 0);
        swatches.push({
            label: `other: ${String(lumped.length)} ${lumped.length === 1 ? "group" : "groups"}`,
            value: lumped.map(valueOf),
            ...swatchPaint(folded),
            count: prepared.counts.other - hiddenCount,
            role: "other",
        });
    }

    return swatches;
}

/**
 * The swatches of an encoding that cuts a numeric domain into groups.
 * @param prepared - The prepared binding.
 * @param domain - The extent it reads values against.
 * @returns One swatch per group, labelled with the values that fall in it.
 */
function groupSwatches(prepared: PreparedBinding, domain: readonly [number, number]): readonly LegendSwatch[] {
    return sweepRuns(prepared, domain).map((run) => ({
        label: run.from === run.to ? formatNumber(run.from) : `${formatNumber(run.from)} - ${formatNumber(run.to)}`,
        value: run.from,
        extent: { min: run.from, max: run.to },
        ...swatchPaint(run.painted),
    }));
}

/**
 * The swatches of a continuous ramp: evenly spaced stops across the domain.
 * @param prepared - The prepared binding.
 * @param domain - The extent it reads values against.
 * @returns The stops, low end first.
 */
function rampSwatches(prepared: PreparedBinding, domain: readonly [number, number]): readonly LegendSwatch[] {
    const [low, high] = domain;
    const span = high - low;
    const stops = span === 0 ? 1 : RAMP_STOPS;
    const swatches: LegendSwatch[] = [];

    for (let step = 0; step < stops; step++) {
        const value = stops === 1 ? low : low + (span * step) / (stops - 1);
        swatches.push({ label: formatNumber(value), value, ...swatchPaint(prepared.paint(value)) });
    }

    return swatches;
}

/**
 * The swatch of a layer that writes one fixed value.
 * @param prepared - The prepared binding, whose paint answers the same thing for every element.
 * @param layer - The layer, whose name is what a fixed value is called in a legend.
 * @returns The one swatch, or none when the fixed value paints nothing.
 */
function literalSwatches(prepared: PreparedBinding, layer: Layer): readonly LegendSwatch[] {
    const painted = prepared.paint(undefined);

    if (painted === undefined) {
        return [];
    }

    return [{ label: layer.name, value: layer.set?.[prepared.channel], ...swatchPaint(painted) }];
}

/**
 * Every swatch one encoding has to show, before the cap.
 * @param prepared - The prepared binding.
 * @param layer - The layer it belongs to.
 * @param sources - Where a run's group ranks come from.
 * @returns The swatches, in the order a legend reads them.
 */
function allSwatches(prepared: PreparedBinding, layer: Layer, sources: LegendSources): readonly LegendSwatch[] {
    if (prepared.path === null) {
        return literalSwatches(prepared, layer);
    }

    if (prepared.categories.length > 0) {
        // ponytail: the order is the map's key order, which JavaScript puts integer-like keys
        // first in ascending order; a numeric ordinal declared high-to-low lists low-to-high.
        return categorySwatches(prepared, Object.keys(authoredRule(layer, prepared.channel)?.map ?? {}), sources);
    }

    if (prepared.domain === null) {
        return [];
    }

    return prepared.groups > 0 ? groupSwatches(prepared, prepared.domain) : rampSwatches(prepared, prepared.domain);
}

// ---------------------------------------------------------------------------------------------
// The block
// ---------------------------------------------------------------------------------------------

/**
 * What shape of legend a consumer draws for one encoding.
 * @param prepared - The prepared binding.
 * @param layer - The layer it belongs to.
 * @returns The kind.
 */
function kindOf(prepared: PreparedBinding, layer: Layer): LegendBlock["kind"] {
    if (prepared.path === null) {
        return layer.kind === "highlight" ? "highlight" : "literal";
    }

    if (prepared.palette !== null) {
        return prepared.palette.kind;
    }

    return prepared.categories.length > 0 ? "categorical" : "sequential";
}

/**
 * The binding a layer authored for one channel, which carries the taste a prepared binding does
 * not keep: the clamp's percentiles, the midpoint, and whether the scale was reversed.
 * @param layer - The layer.
 * @param channel - The channel.
 * @returns The authored binding, or undefined when the layer writes the channel as a fixed value.
 */
function authoredRule(layer: Layer, channel: Channel): Extract<Binding, { by: Path }> | undefined {
    const binding = layer.encode?.[channel];

    return binding !== undefined && "by" in binding ? binding : undefined;
}

/**
 * The extent an encoding read values against, and how it was narrowed.
 * @param prepared - The prepared binding.
 * @param rule - The authored binding, for the clamp and the midpoint it declared.
 * @returns The domain, or undefined when the scale reads no numeric domain.
 */
function domainOf(prepared: PreparedBinding, rule: Extract<Binding, { by: Path }> | undefined): LegendBlock["domain"] {
    if (prepared.domain === null) {
        return undefined;
    }

    const [min, max] = prepared.domain;
    const midpoint = rule?.midpoint;
    const clamp = rule?.clamp;

    return {
        min,
        max,
        ...(midpoint === undefined ? {} : { midpoint }),
        ...(clamp === undefined
            ? {}
            : { clamped: { from: `p${formatNumber(clamp[0])}`, to: `p${formatNumber(clamp[1])}` } }),
    };
}

/**
 * Whether a layer above this one paints the same channel over every element it can reach.
 *
 * `{match:"everything"}` covers without asking about any element. Any other selector covers only
 * when {@link LegendSources.covers} can show it selects every element this layer does -- which is
 * how one run's colours are found hidden under another run's, since both are scoped
 * `{match:"has"}` to what their run measured. Claiming a cover nobody checked would put a
 * departure on a block that is perfectly visible.
 * @param layers - The stack, bottom first.
 * @param at - Where the block's layer sits in it.
 * @param channel - The channel the block describes.
 * @param sources - Where the cover test for a narrower selector comes from.
 * @returns The layer that covers it, or null when nothing does.
 */
function coveredBy(layers: readonly Layer[], at: number, channel: Channel, sources: LegendSources): Layer | null {
    const mine = layers[at];

    for (let above = at + 1; above < layers.length; above++) {
        const layer = layers[above];
        const paints = layer.set?.[channel] !== undefined || layer.encode?.[channel] !== undefined;

        if (!layer.enabled || layer.target !== mine.target || !paints) {
            continue;
        }

        if (layer.selector.match === "everything" || sources.covers?.(layer, mine) === true) {
            return layer;
        }
    }

    return null;
}

/**
 * Everything a reader has to be told about one encoding.
 * @param prepared - The prepared binding, which counted most of them while settling its domain.
 * @param layers - The stack, bottom first.
 * @param at - Where the block's layer sits in it.
 * @param sources - Where the cover test for a narrower selector comes from.
 * @returns The facts, in the order a legend reads them.
 */
function factsOf(
    prepared: PreparedBinding,
    layers: readonly Layer[],
    at: number,
    sources: LegendSources,
): readonly LegendFact[] {
    const covering = coveredBy(layers, at, prepared.channel, sources);

    if (covering === null) {
        return prepared.facts;
    }

    return [...prepared.facts, { code: "legend.painted-over", params: { layerId: covering.id, name: covering.name } }];
}

/** The English sentence the deprecated {@link LegendBlock.departures} carries for each code. */
const SENTENCES: Readonly<Record<LegendFactCode, (text: (name: string) => string) => string>> = {
    "legend.clamped": (text) => `clamped at p${text("from")}/p${text("to")}`,
    "legend.not-plottable": (text) => `${text("count")} not plottable on a ${text("scale")} scale`,
    "legend.none-plottable": (text) => `no value is plottable on a ${text("scale")} scale`,
    "legend.no-value-in-domain": (text) => `no value has a place between ${text("min")} and ${text("max")}`,
    "legend.nothing-measured": () => "nothing measured",
    "legend.unreadable": (text) => `${text("count")} carry no value the scale can read`,
    "legend.lumped": (text) => `${text("count")} lumped into "other"`,
    "legend.not-measured": (text) => `not measured (${text("count")})`,
    "legend.painted-over": (text) => `painted over by "${text("name")}"`,
};

/**
 * The English sentence the deprecated {@link LegendBlock.departures} carries for one fact.
 * @param fact - The fact.
 * @returns The sentence.
 */
function departureSentence(fact: LegendFact): string {
    return SENTENCES[fact.code]((name) => String(fact.params[name]));
}

/**
 * Whether a painted value carries the numbers of a colour.
 * @param value - What the encoding painted.
 * @returns True for a colour with its red, green and blue bytes.
 */
function isRgb(value: unknown): value is { r: number; g: number; b: number } {
    return (
        typeof value === "object" &&
        value !== null &&
        "r" in value &&
        "g" in value &&
        "b" in value &&
        typeof value.r === "number" &&
        typeof value.g === "number" &&
        typeof value.b === "number"
    );
}

/**
 * The relative luminance of a colour (WCAG), which orders colours from dark to light.
 * @param color - The colour, each channel 0 to 255.
 * @param color.r - Red.
 * @param color.g - Green.
 * @param color.b - Blue.
 * @returns The luminance, 0 (black) to 1 (white).
 */
export function luminance({ r, g, b }: { r: number; g: number; b: number }): number {
    const linear = (byte: number): number => {
        const c = byte / 255;
        return c <= 0.040_45 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
    };

    return 0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b);
}

/**
 * Which way the paint moves from one value to another.
 * @param low - What the low end of the domain is painted.
 * @param high - What the high end is painted.
 * @returns The direction, or undefined when the two are not comparable or are the same.
 */
function directionOf(
    low: EncodedValue | undefined,
    high: EncodedValue | undefined,
): LegendReading["params"]["direction"] | undefined {
    if (typeof low === "number" && typeof high === "number") {
        if (high === low) {
            return undefined;
        }

        return high > low ? "larger" : "smaller";
    }

    if (isRgb(low) && isRgb(high)) {
        const from = luminance(low);
        const to = luminance(high);
        if (from === to) {
            return undefined;
        }

        return to < from ? "darker" : "lighter";
    }

    return undefined;
}

/**
 * What a higher value means on the drawing.
 * @param prepared - The prepared binding.
 * @param kind - The block's kind. Only a sequential block has one direction: a diverging palette
 *   is strong at both ends, and a categorical one's colors are unrelated, so neither states one.
 * @returns The reading, or undefined when the encoding has no one direction to state.
 */
function readingOf(prepared: PreparedBinding, kind: LegendBlock["kind"]): LegendReading | undefined {
    const { domain, path } = prepared;
    if (path === null || domain === null || kind !== "sequential" || !(domain[1] > domain[0])) {
        return undefined;
    }

    const direction = directionOf(prepared.paint(domain[0]), prepared.paint(domain[1]));

    return direction === undefined
        ? undefined
        : { code: "legend.higher", params: { channel: prepared.channel, direction, field: path } };
}

/**
 * Build one block.
 * @param layer - The layer it describes.
 * @param prepared - One encoding the layer prepared, which names the channel it paints.
 * @param layers - The stack, bottom first, for the layers that paint over this one.
 * @param at - Where the layer sits in the stack.
 * @param sources - Where the scale's and the field's words come from.
 * @param painted - How many elements the layer is shown on, per channel, when it was counted.
 * @returns The block.
 */
function buildBlock(
    layer: Layer,
    prepared: PreparedBinding,
    layers: readonly Layer[],
    at: number,
    sources: LegendSources,
    painted: Readonly<Partial<Record<Channel, number>>> | undefined,
): LegendBlock {
    const { channel } = prepared;
    const rule = authoredRule(layer, channel);
    const kind = kindOf(prepared, layer);
    const all = markPaintedOver(allSwatches(prepared, layer, sources), kind, () => sources.reach?.(layer.id, channel));
    const capped = capSwatches(all);
    const { path, scale } = prepared;
    const domain = domainOf(prepared, rule);
    const reading = readingOf(prepared, kind);
    const { range } = prepared;
    const facts = factsOf(prepared, layers, at, sources);
    const selects = layer.selector.match === "everything" ? undefined : sources.selects?.(layer.id);
    const scoped = selects !== undefined && selects.count < selects.of;

    const block: LegendBlock = {
        channel,
        layerId: layer.id,
        ...(layer.source.by === "run" ? { runId: layer.source.runId } : {}),
        kind,
        ...(path === null ? {} : { field: { ...fieldWords(path, layer.target, sources), path } }),
        ...(scale === null
            ? {}
            : { scale: { kind: scale, label: sources.scales.describe(scale)?.plainName ?? scale } }),
        ...(domain === undefined ? {} : { domain }),
        ...(reading === undefined ? {} : { reading }),
        ...(range === undefined ? {} : { range: { min: Math.min(...range), max: Math.max(...range) } }),
        ...(prepared.palette === null
            ? {}
            : { palette: { name: prepared.palette.id, reversed: rule?.reverse === true } }),
        swatches: Object.freeze(capped.swatches),
        ...(painted === undefined ? {} : { painted: painted[channel] ?? 0 }),
        ...(scoped ? { scope: { count: selects.count, of: selects.of } } : {}),
        ...(capped.hidden === 0 ? {} : { overflow: { hidden: capped.hidden } }),
        facts: Object.freeze([...facts]),
        departures: Object.freeze(facts.map(departureSentence)),
    };
    UNCAPPED.set(block, all);
    return block;
}

/**
 * The rows of a categorical block, each row no element shows marked with the layer that paints
 * over it ({@link LegendSwatch.paintedOverBy}).
 * @param rows - The rows.
 * @param kind - The block's kind; only a categorical block's rows are values elements carry.
 * @param reach - Reads what each category reaches, once, when there is a row to mark.
 * @returns The rows, marked.
 */
function markPaintedOver(
    rows: readonly LegendSwatch[],
    kind: LegendBlock["kind"],
    reach: () => ReadonlyMap<string, ValueReach> | undefined,
): readonly LegendSwatch[] {
    const met = kind === "categorical" ? reach() : undefined;
    if (met === undefined) {
        return rows;
    }
    return rows.map((row) => {
        const at = row.role === "other" || row.hidden === true ? undefined : met.get(String(row.value));
        return at !== undefined && at.carried > 0 && at.shown === 0 && at.coveredBy !== undefined
            ? { ...row, paintedOverBy: at.coveredBy }
            : row;
    });
}

/** Every row a block had before the cap, for {@link foldCopies} to choose from. */
const UNCAPPED = new WeakMap<LegendBlock, readonly LegendSwatch[]>();

/**
 * At most {@link SWATCH_CAP} rows, plus the `"other"` row, which is what the paint folded and so
 * is kept whatever the cap drops.
 * @param all - Every row.
 * @returns The rows kept and how many were left out.
 */
function capSwatches(all: readonly LegendSwatch[]): { swatches: LegendSwatch[]; hidden: number } {
    const other = all.at(-1)?.role === "other" ? all.at(-1) : undefined;
    const rows = other === undefined ? all : all.slice(0, -1);
    const hidden = Math.max(0, rows.length - SWATCH_CAP);
    const kept = rows.slice(0, SWATCH_CAP);
    return { swatches: other === undefined ? kept : [...kept, other], hidden };
}

// ---------------------------------------------------------------------------------------------
// The door
// ---------------------------------------------------------------------------------------------

/**
 * Read the legend out of the encoding model.
 *
 * SYNCHRONOUS, and it paints nothing: every figure it prints was worked out when the bindings
 * were prepared, except each block's `painted` count, which walks the layer's elements once. The one cost it adds is the sweep that finds a stepped
 * encoding's group boundaries, which is a few hundred calls into a closure per block.
 *
 * THE BASE LAYERS ARE NOT IN IT. A layer of kind "base" is what the picture looks like when
 * nothing has been said about the data, and a legend is a list of the things that HAVE been said.
 * A consumer that wants the defaults too reads `styles.list()`, which has them.
 *
 * A DISABLED LAYER IS NOT IN IT EITHER, because it paints nothing, and a legend row for paint
 * nobody can see is the false claim this whole file is arranged against.
 * @param sources - The stack, the prepared encodings, the scales and the field names.
 * @returns The blocks, BOTTOM FIRST -- the same order `styles.list()` returns.
 */
export function buildLegend(sources: LegendSources): readonly LegendBlock[] {
    const layers = sources.layers();
    const blocks: LegendBlock[] = [];

    for (let at = 0; at < layers.length; at++) {
        const layer = layers[at];

        if (!layer.enabled || layer.kind === "base") {
            continue;
        }

        const all = sources.encoding(layer.id);
        const prepared = sources.holdsBase?.(layer) === true ? all.filter((each) => each.path !== null) : all;
        // ponytail: one count per layer per read, a walk over that layer's elements; memoize by
        // the counts' revision if legend reads ever show up in a profile.
        const painted = prepared.length === 0 ? undefined : sources.painted?.(layer.id);
        for (const binding of prepared) {
            blocks.push(buildBlock(layer, binding, layers, at, sources, painted));
        }
    }

    return blocks.length === 0 ? NO_BLOCKS : Object.freeze(foldCopies(blocks, layers, sources.reached));
}

/**
 * Fold the blocks of copies of one binding in several layers into one, which lists
 * every layer it stands for and the elements they paint together. Copies that differ only in
 * their value tables (`map`) are copies too -- a binding copied into each of a folder's group
 * layers keeps each group's colour in its own table, so the colour follows the group across a
 * re-run -- and the folded block lists the categories the copies meet among the elements they
 * select, each painted as the copy that meets it paints it.
 * @param blocks - The blocks, bottom first.
 * @param layers - The stack.
 * @param reached - The categories a layer's binding meets, when the sources can say.
 * @returns The blocks, each binding once.
 */
function foldCopies(
    blocks: readonly LegendBlock[],
    layers: readonly Layer[],
    reached: LegendSources["reached"],
): LegendBlock[] {
    const byId = new Map(layers.map((layer) => [layer.id, layer]));
    const groups = new Map<string, LegendBlock[]>();
    const order: (LegendBlock | LegendBlock[])[] = [];
    for (const block of blocks) {
        const binding = byId.get(block.layerId)?.encode?.[block.channel];
        if (binding === undefined || !("by" in binding)) {
            order.push(block);
            continue;
        }
        const { map: _map, ...rest } = binding;
        const key = `${block.channel}|${JSON.stringify(rest)}`;
        const group = groups.get(key);
        if (group === undefined) {
            const fresh = [block];
            groups.set(key, fresh);
            order.push(fresh);
        } else {
            group.push(block);
        }
    }
    return order.map((entry) => (Array.isArray(entry) ? foldGroup(entry, reached) : entry));
}

/**
 * One block for several copies of a binding (see {@link foldCopies}).
 * @param copies - The copies' blocks, bottom first.
 * @param reached - The categories a layer's binding meets, when the sources can say.
 * @returns The folded block, or the one block of a binding with no copies.
 */
function foldGroup(copies: readonly LegendBlock[], reached: LegendSources["reached"]): LegendBlock {
    if (copies.length === 1) {
        return copies[0];
    }
    // The copy shown on the most elements speaks for the rest: a copy painted over everywhere (a
    // one-node layer under a layer that binds every node the same way) holds a domain read over
    // its own few elements, so a block named for it kept that layer and lost the range drawn.
    const kept = copies.reduce((best, copy) => ((copy.painted ?? 0) > (best.painted ?? 0) ? copy : best));
    const painted = copies.some((copy) => copy.painted !== undefined)
        ? { painted: copies.reduce((sum, copy) => sum + (copy.painted ?? 0), 0) }
        : {};
    // The copies' selections together; every element of the kind, and the block has no scope.
    const together = copies.every((copy) => copy.scope !== undefined)
        ? copies.reduce((sum, copy) => sum + (copy.scope?.count ?? 0), 0)
        : undefined;
    const { scope: _scope, ...keptRest } = kept;
    const of = kept.scope?.of ?? 0;
    const folded = {
        ...keptRest,
        layers: Object.freeze(copies.map((copy) => copy.layerId)),
        ...painted,
        ...(together !== undefined && together < of ? { scope: { count: together, of } } : {}),
    };
    // A ramp's rows are samples along the domain, not categories an element carries: kept whole,
    // or the ramp lost both its end values to the category filter below.
    if (kept.kind === "sequential" || kept.kind === "diverging") {
        return Object.freeze(folded);
    }
    const met = copies.map((copy) => reached?.(copy.layerId, copy.channel));
    if (met.includes(undefined)) {
        return Object.freeze(folded);
    }
    // Each category once, painted as the copy that meets it paints it, in the kept copy's order.
    const rank = new Map((UNCAPPED.get(kept) ?? kept.swatches).map((swatch, at) => [String(swatch.value), at]));
    const seen = new Set<string>();
    const rows: LegendSwatch[] = [];
    let other: LegendSwatch | undefined;
    copies.forEach((copy, at) => {
        const categories = met[at] ?? new Set<string>();
        for (const swatch of UNCAPPED.get(copy) ?? copy.swatches) {
            if (swatch.role === "other") {
                // The bucket stays when a copy meets a category folded into it.
                const folds = Array.isArray(swatch.value) ? swatch.value : [];
                other ??= folds.some((value) => categories.has(String(value))) ? swatch : undefined;
                continue;
            }
            const category = String(swatch.value);
            const key = `${category}|${JSON.stringify(swatch.paints ?? swatch.color ?? null)}`;
            if (categories.has(category) && !seen.has(key)) {
                seen.add(key);
                rows.push(swatch);
            }
        }
    });
    rows.sort((a, b) => (rank.get(String(a.value)) ?? Infinity) - (rank.get(String(b.value)) ?? Infinity));
    const capped = capSwatches(other === undefined ? rows : [...rows, other]);
    const { overflow: _overflow, ...rest } = folded;
    // Nothing the copies meet is folded into "other" when no copy keeps the bucket's row.
    const facts = other === undefined ? kept.facts.filter((fact) => fact.code !== "legend.lumped") : kept.facts;
    return Object.freeze({
        ...rest,
        swatches: Object.freeze(capped.swatches),
        ...(capped.hidden === 0 ? {} : { overflow: { hidden: capped.hidden } }),
        facts: Object.freeze(facts),
        departures: Object.freeze(facts.map(departureSentence)),
    });
}

/**
 * The blocks one layer draws, whether or not the legend lists it: a base layer is answered like
 * any other. A hidden layer answers none, because a hidden layer paints nothing.
 * @param sources - What the legend is read from.
 * @param layerId - The layer.
 * @returns The layer's blocks, one per channel it paints, or undefined when the stack holds no
 *     layer with that id.
 */
export function buildLayerLegend(sources: LegendSources, layerId: LayerId): readonly LegendBlock[] | undefined {
    const layers = sources.layers();
    const at = layers.findIndex((layer) => layer.id === layerId);

    if (at === -1) {
        return undefined;
    }

    const layer = layers[at];
    const painted = layer.enabled ? sources.painted?.(layerId) : undefined;
    const blocks = layer.enabled
        ? sources.encoding(layerId).map((prepared) => buildBlock(layer, prepared, layers, at, sources, painted))
        : [];

    return blocks.length === 0 ? NO_BLOCKS : Object.freeze(blocks);
}
