/**
 * @file Strict state: extra checks that project state is only ever changed through the
 * dispatcher, switched on in the element's own tests and by anyone who wants them.
 *
 * The switch is the global `globalThis.__GRAPHTY_STRICT_STATE__ = true`, set before a session is
 * created. A global rather than an environment variable, because browsers have no `process` and
 * the published bundle must not touch it. In Node, `GRAPHTY_STRICT_STATE=1` works too; it is
 * read through `globalThis.process`, so where there is none nothing throws. See
 * design/undo/undo-design.md section 12.1.
 */

import { GraphtyError } from "../../errors/GraphtyError";

/**
 * Whether strict state is on. Read once per store, when it is created.
 * @returns True when the global or, in Node, the environment variable asks for it.
 */
export function strictStateEnabled(): boolean {
    const scope = globalThis as {
        __GRAPHTY_STRICT_STATE__?: unknown;
        process?: { env?: Record<string, string | undefined> };
    };

    return scope.__GRAPHTY_STRICT_STATE__ === true || scope.process?.env?.GRAPHTY_STRICT_STATE === "1";
}

/**
 * The error a failed strict check throws: a broken invariant, so a bug in the element.
 * @param what - What was found, as a sentence fragment.
 * @returns The error, to throw.
 */
export function strictViolation(what: string): GraphtyError {
    return new GraphtyError({
        code: "E_INTERNAL",
        message: `Strict state: ${what}.`,
        source: "history",
    });
}

/**
 * Strict: an op-log key (a node or edge id, or a whole `graph` or `pins` slice) being acquired by
 * one open group must not already be held by another, because an op-log cannot hand a key over.
 * @param key - The key being acquired.
 * @param holder - The label of the other open group holding it, or null when none does.
 */
export function checkSoleHolder(key: string, holder: string | null): void {
    if (holder !== null) {
        throw strictViolation(`${key} is being acquired while the open group "${holder}" holds it`);
    }
}

/**
 * Strict: a command dispatched inline through a group-tagged facade touches only keys that are
 * free or held by its own group (design section 4.5).
 * @param op - The inline command's op.
 * @param key - The op-log key another group holds.
 * @param holder - The label of that group.
 */
export function checkInlineKey(op: string, key: string, holder: string): void {
    throw strictViolation(
        `"${op}", dispatched inline through a plugin's graph facade, needs ${key}, which "${holder}" holds`,
    );
}

// ---------------------------------------------------------------------------------------------
// Retained typed arrays
// ---------------------------------------------------------------------------------------------

/** A typed array state keeps, with what it was when first kept. */
interface Retained {
    readonly array: WeakRef<ArrayBufferView>;
    /** What holds it, for the message: "the arrangement slice's capture". */
    readonly what: string;
    readonly sum: number;
}

/**
 * Every array retained, and each holder's own: a dispatch checks the arrays its own state keeps,
 * so its cost does not grow with every other session alive in the process; the sweep after each
 * test checks them all.
 */
const retained = {
    all: new Set<Retained>(),
    byArray: new WeakMap<ArrayBufferView, Retained>(),
    byHolder: new WeakMap<object, Set<Retained>>(),
    /** Retained with no holder since a dispatch last checked them; the next dispatch checks them once. */
    fresh: new Set<Retained>(),
};

/**
 * Forget an array once it is collected. A WeakRef only clears at a full collection, which a
 * roomy heap may not run for thousands of dispatches, so nothing a dispatch walks may depend on
 * one clearing; this only keeps `all` from growing by one entry per array ever retained.
 */
const collected = new FinalizationRegistry<Retained>((entry) => {
    retained.all.delete(entry);
});

/** How many array checks have run, for the tests that bound a dispatch's share. */
let verifications = 0;

/**
 * A checksum of an array's bytes (FNV-1a over 32-bit words where the view is aligned to them,
 * over bytes where it is not), or -1 for one whose buffer was detached. Every dispatch sums every
 * array its state keeps, several megabytes at the render ceiling, so it reads a word at a time.
 * Each step is a bijection of the running sum, so a change to any one word always changes it.
 * @param array - The array.
 * @returns The checksum.
 */
function checksum(array: ArrayBufferView): number {
    if (array.buffer.byteLength === 0 && array.byteLength === 0) {
        return -1;
    }

    const { buffer, byteOffset, byteLength } = array;
    const units =
        byteOffset % 4 === 0 && byteLength % 4 === 0
            ? new Int32Array(buffer, byteOffset, byteLength / 4)
            : new Uint8Array(buffer, byteOffset, byteLength);
    let sum = 0x811c9dc5;
    for (let at = 0; at < units.length; at++) {
        sum = Math.imul(sum ^ (units[at] ?? 0), 0x01000193);
    }

    return sum >>> 0;
}

/**
 * Strict: note a typed array state has just come to keep. Typed arrays cannot be frozen, so its
 * bytes are summed now, and a later check that finds them changed names what holds it. Nothing
 * happens when strict state is off, or for an array already noted.
 * @param array - The array.
 * @param what - What holds it, as a noun phrase naming the slice.
 * @param holder - The object whose state keeps it (a store's snapshot), whose dispatcher checks it
 *     at each dispatch. Absent, the next dispatch checks it once, and after that a dispatch checks
 *     it only while its state names it (see {@link verifyRetainedArrays}).
 */
export function retainArray(array: ArrayBufferView, what: string, holder?: object): void {
    if (!strictStateEnabled() || retained.byArray.has(array)) {
        return;
    }

    const entry = { array: new WeakRef(array), what, sum: checksum(array) };
    retained.byArray.set(array, entry);
    retained.all.add(entry);
    collected.register(array, entry);
    if (holder === undefined) {
        retained.fresh.add(entry);
        return;
    }

    let own = retained.byHolder.get(holder);
    if (own === undefined) {
        own = new Set();
        retained.byHolder.set(holder, own);
    }

    own.add(entry);
}

/**
 * Throw when one retained array's bytes changed.
 * @param entry - The array.
 * @returns False when the array has been collected.
 */
function verify(entry: Retained): boolean {
    const array = entry.array.deref();
    if (array === undefined) {
        return false;
    }

    verifications++;
    const sum = checksum(array);
    if (sum !== -1 && sum !== entry.sum) {
        throw strictViolation(
            `${entry.what} was written in place after state kept it; typed arrays in state are never written`,
        );
    }

    return true;
}

/**
 * Strict: check the retained arrays still alive: the ones a dispatch's state keeps, as each
 * dispatch does, or every one, as the test setup does after each test. A dispatch checks the given
 * holders' arrays, the given arrays its state names, and the arrays retained with no holder since
 * the last dispatch -- never every array not yet collected, which grows with every capture ever
 * taken until the next full collection (issue #584).
 * @param holders - The holders whose arrays to check; every array when absent.
 * @param kept - Arrays the dispatch's state names (its captures and row patches); one never
 *     retained is skipped.
 */
export function verifyRetainedArrays(
    holders?: readonly (object | null)[],
    kept: Iterable<ArrayBufferView | null | undefined> = [],
): void {
    const sets =
        holders === undefined
            ? [retained.all]
            : [
                  retained.fresh,
                  ...holders.flatMap((holder) => {
                      const own = holder === null ? undefined : retained.byHolder.get(holder);
                      return own === undefined ? [] : [own];
                  }),
              ];

    for (const set of sets) {
        for (const entry of set) {
            if (!verify(entry)) {
                set.delete(entry);
                retained.all.delete(entry);
            }
        }
    }

    retained.fresh.clear();
    for (const array of kept) {
        const entry = array === null || array === undefined ? undefined : retained.byArray.get(array);
        if (entry !== undefined) {
            verify(entry);
        }
    }
}

/**
 * Strict: how many array checks have run since the module loaded. A test reads it on both sides of
 * a dispatch to bound what one dispatch checks.
 * @returns The count.
 */
export function strictArrayChecks(): number {
    return verifications;
}

/**
 * Strict: the graph store's builder was changed by something other than the graph primitives.
 * @param count - How many mutations nobody accounted for.
 * @returns The error, to throw.
 */
export function builderDrift(count: number): GraphtyError {
    return strictViolation(
        `the graph slice's builder was mutated ${String(count)} time(s) outside a command; ` +
            "dispatch data.apply or data.import instead of writing the store",
    );
}

// The test setup sweeps every retained array after each test, and reaches this through a global
// so that the setup file imports nothing from the element. Only where strict state is on.
if (strictStateEnabled()) {
    (globalThis as { __GRAPHTY_STRICT_SWEEP__?: () => void }).__GRAPHTY_STRICT_SWEEP__ = () => {
        verifyRetainedArrays();
    };
}

/**
 * Hand an error the element caught and carried on past -- the render loop's catch, a lane hook
 * that reports and goes on -- to whoever is watching: the element's own tests install
 * `globalThis.__GRAPHTY_CAUGHT__` and fail the test it happened in. Nothing is installed in
 * production, so this does nothing there.
 * @param error - What was caught.
 */
export function reportCaught(error: unknown): void {
    (globalThis as { __GRAPHTY_CAUGHT__?: (error: unknown) => void }).__GRAPHTY_CAUGHT__?.(error);
}
