/** How many left-out edge rows a load keeps with its source, so a reader can still see them. */
const LEFT_OUT_KEPT = 100;

/**
 * The column an endpoint expression reads: the name itself, or a quoted name unquoted (as a draft
 * writes a column name that is not a plain identifier).
 * @param expression - The JMESPath expression.
 * @returns The column's name, or null for any other expression.
 */
function columnOf(expression: string): string | null {
    if (/^[A-Za-z_]\w*$/.test(expression)) {
        return expression;
    }

    if (/^"(?:[^"\\]|\\.)*"$/.test(expression)) {
        return JSON.parse(expression) as string;
    }

    return null;
}

/**
 * A left-out edge row as its source keeps it: the two ends, its line when a draft gave one, and the
 * row's other values (the columns the ends were read from left out, when they are plain column names).
 * @param edge - the row.
 * @param source - its source end.
 * @param target - its target end.
 * @param endpoints - where the ends were read from.
 * @param line - the row's line, or undefined.
 * @param missingEnds - the ends that name no node.
 * @returns the frozen entry.
 */
function leftOutEdge(
    edge: Readonly<Record<string | number, unknown>>,
    source: NodeIdType,
    target: NodeIdType,
    endpoints: ResolvedEndpoints,
    line: number | undefined,
    missingEnds: readonly EdgeEnd[],
): LeftOutEdge {
    const ends = new Set([columnOf(endpoints.source), columnOf(endpoints.target)]);
    const values = Object.fromEntries(Object.entries(edge).filter(([key]) => !ends.has(key)));
    return Object.freeze({
        source,
        target,
        ...(line === undefined ? {} : { line }),
        values: frozenRecord(values),
        missingEnds: Object.freeze([...missingEnds]),
    });
}
import type { DirectionOutcome, GraphWriter } from "./graphOps";

/**
 * The kinds a draft gave the rows it hands over, by those rows: the report's `kinds`. Kept beside
 * the rows rather than in them, as `HELD_READERS` keeps their reader.
 */
export const HELD_KINDS = new WeakMap<HeldRows, NonNullable<LoadReport["kinds"]>>();

/**
 * A load's input token as its `data.sources()` entry keeps it, out of sight of the entry's type.
 * @param command - The import.
 * @param command.input - The token, when the rows were read from something the session holds.
 * @returns `{ input }`, or nothing.
 */
function inputOf(command: { readonly input?: string }): { readonly input?: string } {
    return command.input === undefined ? {} : { input: command.input };
}

/**
 * Whether a value may be used as a graph-format node id.
 *
 * graph-format accepts a string or a FINITE number and throws `E_INVALID_ID` for anything else
 * (`graph-format/src/ids/node-id-map.ts`). The element is looser: a node id is whatever the
 * configured JMESPath expression returns, which is `null` for a record that does not carry the
 * key at all, and the element has always let such a record through and rendered it. So the id is
 * CHECKED here rather than thrown on -- an unusable id leaves the render object exactly as it is
 * today and keeps it out of the store, which is the one place the id has to be real.
 * @param id - the extracted id
 * @returns true when graph-format will accept it
 */
export function isStorableId(id: unknown): id is string | number {
    return typeof id === "string" || (typeof id === "number" && Number.isFinite(id));
}

/**
 * Whether a weight can be STORED: the snapshot keeps its arc weights as f32, so a finite double
 * above the f32 range (about 3.4e38) would become Infinity there, and every algorithm that needs
 * finite weights would refuse the whole graph. Such a weight is treated like an infinite one.
 * @param value - the candidate weight
 * @returns true when it is a number that stays finite after the round to f32
 */
function isStorableWeight(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(Math.fround(value));
}

/**
 * Resolve an edge weight: the configured path, then the legacy "value" key, then 1.
 *
 * The second probe exists because the conversion this replaced hard-coded a `value` weight key, so
 * every weighted dataset, fixture and story in this repository carries `value` and nothing carries
 * `weight`. Reading only the configured path would silently re-read all of them as unweighted.
 * The probe is removed once nothing ships a `value` key.
 * @param record - the raw edge record
 * @param path - `config.data.knownFields.edgeWeightPath`; null means "do not look"
 * @param legacyFallback - false when the reader named the weight column, so `value` is not read
 * @returns the weight and which probe produced it
 */
export function resolveEdgeWeight(
    record: Record<string | number, unknown>,
    path: string | null,
    legacyFallback = true,
): { weight: number; source: "path" | "legacy" | "default" } {
    const fromPath = path === null || !Object.hasOwn(record, path) ? undefined : record[path];
    if (isStorableWeight(fromPath)) {
        return { weight: fromPath, source: "path" };
    }

    const legacy = legacyFallback ? record.value : undefined;
    if (isStorableWeight(legacy)) {
        return { weight: legacy, source: "legacy" };
    }

    return { weight: 1, source: "default" };
}

/**
 * The number in a load key (`s3` is 3), so the next key is past every key a list holds.
 * @param key - The key, or undefined for an entry saved before loads had keys.
 * @returns The number, or 0.
 */
function serialOf(key: string | undefined): number {
    const match = /^s(\d+)$/.exec(key ?? "");
    return match === null ? 0 : Number(match[1]);
}

/** What a caller may say about one `addEdges` call that the configuration does not already say. */
export interface AddEdgesOptions {
    /** The JMESPath expression naming the source endpoint, overriding the configured one. */
    readonly source?: string;
    /** The JMESPath expression naming the target endpoint, overriding the configured one. */
    readonly target?: string;
    /**
     * What to do with a record naming an ordered pair the graph already holds, overriding
     * `data.knownFields.repeatedEdges` for this call alone.
     *
     * The expand-a-node path passes `"first"`, because "fetch the neighbourhood of this node" is a
     * request that legitimately re-supplies edges the graph already has, and the element knows
     * that about its own call site.
     */
    readonly repeated?: DuplicatePolicy;
    /**
     * The record key weights are read from, overriding `data.knownFields.edgeWeightPath`, with no
     * `value` fallback; null reads none.
     */
    readonly weight?: string | null;
}

/** An edge the graph already holds, as the host hands it back; the host may carry more. */
interface KnownEdge {
    /** The edge's index in the builder. */
    readonly edgeIndex: number;
}

/** One edge record the store has just taken. */
export interface StoredEdge {
    /** The raw edge record. */
    readonly record: Record<string | number, unknown>;
    /** The source endpoint id, resolved once for the batch. */
    readonly sourceId: NodeIdType;
    /** The target endpoint id, resolved once for the batch. */
    readonly targetId: NodeIdType;
    /** The edge's index in the builder. */
    readonly edgeIndex: number;
    /** The counter the store stamped into this edge's id column. */
    readonly edgeId: number;
}

/**
 * What ingest needs from whoever draws the graph.
 *
 * Every question about an edge the graph already holds comes here because the host is what knows
 * both halves of it: an edge with a render object and an edge still waiting for its endpoints. A
 * repeat policy has to be able to reach both -- a `sum` that ignored a waiting edge would lose a
 * weight, and a `first` that ignored it would create the second edge it exists to prevent.
 * @template K - the host's own description of an existing edge
 */
export interface IngestHost<K extends KnownEdge> {
    /** The store records are written into; asked each time, because clearing replaces it. */
    store(): GraphStore;
    /** The data configuration; asked each time, because the element edits it in place. */
    dataConfig(): Styles["config"]["data"];
    /** Whether a node with this id is already held, so a re-supplied node is skipped. */
    hasNode(id: NodeIdType): boolean;
    /** How many nodes are held, for the ceiling. */
    nodeCount(): number;
    /** Every edge between one ordered pair, oldest first. */
    edgesBetween(sourceId: NodeIdType, targetId: NodeIdType): readonly K[];
    /** The edge occupying one store row, or null. */
    edgeAt(edgeIndex: number): K | null;
    /** Replace the attributes an existing edge carries (the `last` repeat policy). */
    replaceEdgeRecord(known: K, record: Record<string | number, unknown>): void;
    /** A node the store has just taken; `index` is `INVALID_INDEX` for an id it will not hold. */
    nodeStored(id: NodeIdType, record: Record<string | number, unknown>, index: number): void;
    /** An edge the store has just taken. */
    edgeStored(edge: StoredEdge): void;
    /** Rows have been removed from the store; whatever draws them goes. */
    rowsRemoved(nodes: readonly NodeIdType[], edges: readonly EdgeId[]): void;
    /** The graph has been emptied. */
    cleared(): void;
    /** A non-empty batch of node records has been ingested. */
    nodesArrived(count: number): void;
    /** A non-empty batch of edge records has been ingested. */
    edgesArrived(count: number): void;
    /** A chunk of a load has been ingested. */
    loadProgress(progress: LoadProgress): void;
    /** A load finished and its source counted errors along the way. */
    loadErrors(format: string, errors: ErrorAggregator): void;
    /** A load finished. */
    loadComplete(format: string, report: ImportReport, progress: LoadProgress, duration: number, errors: number): void;
    /** A load failed after `progress.chunks` chunks. */
    loadFailed(format: string, error: Error, progress: LoadProgress): void;
    /** Where the session's `progress:changed` is fed from: every chunk, and once at the end. */
    progress?(change: ProgressChange): void;
}

/**
 * A load's progress as the session publishes it. A load cannot know its record count in advance,
 * so it reports records read and no total.
 * @param progress - How far the load has got.
 * @param phase - Whether it is still going.
 * @param end - How it ended, on its last change.
 * @returns The change.
 */
function loadProgressChange(
    progress: LoadProgress,
    phase: ProgressChange["phase"],
    end?: Pick<ProgressChange, "outcome" | "error">,
): ProgressChange {
    return {
        task: "load",
        phase,
        completed: progress.nodeRecords + progress.edgeRecords,
        total: null,
        fraction: null,
        ...(progress.source === undefined ? {} : { source: progress.source }),
        ...end,
    };
}

/**
 * What a load's progress names as its source: the name it was given or its file's, and its URL.
 * @param opts - The data source's options.
 * @param name - The name the import was given.
 * @returns The source, or undefined when nothing names it.
 */
export function progressSource(opts: object, name: string | undefined): ProgressChange["source"] {
    const { url, file, filename } = opts as { url?: unknown; file?: { name?: unknown }; filename?: unknown };
    const link = typeof url === "string" && !url.startsWith("data:") ? url : undefined;
    const named = [name, filename, file?.name, link?.split(/[?#]/)[0]?.split("/").pop()].find(
        (each): each is string => typeof each === "string" && each !== "",
    );
    if (named === undefined && link === undefined) {
        return undefined;
    }

    return Object.freeze({
        ...(named === undefined ? {} : { name: named }),
        ...(link === undefined ? {} : { url: link }),
    });
}

/**
 * How a failed load ended, for its last progress change.
 * @param error - What it threw.
 * @param signal - Its cancel signal.
 * @returns The outcome, and the coded error when it carried one.
 */
export function failedEnd(error: unknown, signal: AbortSignal | undefined): Pick<ProgressChange, "outcome" | "error"> {
    if (signal?.aborted === true) {
        return { outcome: "cancelled" };
    }

    return isGraphtyError(error)
        ? { outcome: "failed", error: Object.freeze({ code: error.code, details: error.details ?? {} }) }
        : { outcome: "failed" };
}

/**
 * The refusal of a source whose parser could not read it: one that produced no record and
 * reported a parse error. An empty file, or one whose rows were all refused by its schema, is
 * not this; it is `E_EMPTY_LOAD`.
 * @param format - The data source that read it.
 * @param errors - The errors its read reported.
 * @returns `E_PARSE_FAILED` naming the format and, when known, the line; null when no parse error.
 */
export function unreadableSource(format: string, errors: readonly DataLoadingError[]): GraphtyError | null {
    const unreadable = errors.find((each) => each.category === "parse-error");
    if (unreadable === undefined) {
        return null;
    }

    return new GraphtyError({
        code: "E_PARSE_FAILED",
        source: "data",
        message: `The ${format} source could not be read: ${unreadable.message}`,
        details: {
            format,
            rowErrors: errors.length,
            ...(unreadable.line === undefined ? {} : { line: unreadable.line }),
        },
    });
}

/** How far a load has got. */
interface LoadProgress {
    /** The data source being read. */
    readonly format: string;
    /** The file size the caller passed, when it passed one. */
    readonly fileSize: number | undefined;
    /** Node RECORDS the source has handed over so far. */
    readonly nodeRecords: number;
    /** Edge RECORDS the source has handed over so far. */
    readonly edgeRecords: number;
    /** Chunks ingested so far. */
    readonly chunks: number;
    /** What is being read, as progress names it. */
    readonly source?: ProgressChange["source"];
}

/**
 * Whether a value read from `knownFields.edgeIdPath` can identify an edge.
 *
 * A Map keyed on anything else would hold one entry per object identity, so every record would be
 * its own edge and the setting would silently do nothing.
 * @param value - what the configured expression returned
 * @returns true when it is usable as a record identifier
 */
function isStorableRecordId(value: unknown): value is string | number {
    return typeof value === "string" || (typeof value === "number" && Number.isFinite(value));
}

/** What one `addEdges` batch is resolved to before its records are added. */
interface EdgeBatch {
    /** The endpoint expressions the batch answers. */
    readonly endpoints: ResolvedEndpoints;
    /** The repeat policy for this call. */
    readonly policy: DuplicatePolicy;
    /** Where a record's own id is read, or null when none is. */
    readonly recordIdPath: string | null;
    /** Where a record's weight is read, or null when none is. */
    readonly weightPath: string | null;
    /** Whether the legacy `value` key is read when the weight path answers nothing. */
    readonly legacyFallback: boolean;
    /** The counters of the load or call. */
    readonly tally: ImportTally;
}

/**
 * Turns node and edge records, and whole data sources, into the graph a host holds.
 *
 * One per graph. It keeps what outlives a single call: the record identifiers already seen, the
 * last import report, and -- while a load is in progress -- the load's tally and the endpoint
 * spelling its first edge chunk settled on.
 * @template K - the host's own description of an existing edge
 */

/**
 * The tables an import names: the draft's, or else the one named source it read, as a draft of it
 * names its one table, so a file loads the same whichever door it came in by.
 * @param command - The import.
 * @returns The table names.
 */
function tablesOf(command: DataImportCommand): readonly string[] {
    return Object.freeze([...(command.tables ?? (command.source.name === undefined ? [] : [command.source.name]))]);
}

/**
 *
 */
export class Ingest<K extends KnownEdge> {
    private readonly logger: Logger = GraphtyLogger.getLogger(["graphty", "data"]);

    /**
     * The store edge index each record identifier has already produced, when
     * `knownFields.edgeIdPath` names one. Empty when it does not, which is the default.
     */
    private readonly edgesByRecordId = new Map<string | number, number>();

    /**
     * The endpoint expressions the load in progress resolved, so a chunked load probes ONCE.
     *
     * A file that spells one chunk's edges `source`/`target` and the next chunk's `from`/`to` is a
     * broken file, and letting each chunk decide for itself makes the answer both unreportable and
     * dependent on how the file happened to be split.
     */
    private loadEndpoints: ResolvedEndpoints | null = null;

    /** The tally the load in progress is counting into, or null outside a load. */
    private loadTally: ImportTally | null = null;
    /** The tally of the load that finished last, which `importSource` reads its issue facts from. */
    private sealedTally: ImportTally | null = null;

    /** Endpoints an edge of the load in progress created with no node record to draw them from. */
    private readonly loadMadeEndpoints = new Set<NodeIdType>();

    /** The load in progress drops an edge naming a node no node record holds. */
    private leaveOutUnmatched = false;

    /** The edge rows the load in progress left out, up to {@link LEFT_OUT_KEPT}. */
    private leftOutEdges: LeftOutEdge[] = [];

    /** The columns the load in progress read the left-out rows' ends from, when plain names. */
    private leftOutEnds: { source: string; target: string } | null = null;

    /** Each edge record's line in the draft the load in progress reads, or null when it reads no draft. */
    private loadEdgeLines: readonly number[] | null = null;

    /** What the load in progress does with a node record repeating an id an earlier one gave. */
    private duplicateIds: NonNullable<DataImportCommand["duplicateIds"]> = "first";
    /** For a merge: whether a node already in the graph takes the incoming attributes. */
    private updateExisting = false;

    /** The graph held nodes when the load in progress began, so its edges can name them. */
    private loadBeganWithNodes = false;

    /** While a draft's load is measured: the graph it counts as already there. */
    private measure: NonNullable<DataImportCommand["measure"]> | null = null;

    /** The ids the load in progress named, for its entry in `provenance`; null outside a load. */
    private supplied: { readonly nodes: Set<NodeId>; readonly edges: Set<EdgeId> } | null = null;

    /** The highest load key number handed out, so a key is never handed out twice. */
    private sourceSerial = 0;

    /**
     * Start with no records seen and no report.
     * @param host - what draws the graph, and knows which edges it already holds
     */
    constructor(private readonly host: IngestHost<K>) {}

    /**
     * Whether a load from a data source is still streaming records in.
     * @returns true between a load's first chunk and its end
     */
    get isLoading(): boolean {
        return this.loadTally !== null;
    }

    /** Forget everything about the graph that was: called when the host discards its store. */
    reset(): void {
        this.edgesByRecordId.clear();
    }

    /**
     * Carry out one `data.apply` mutation.
     * @param mutation - The mutation.
     * @param writer - The command's writer.
     * @param resolve - The id a row is held under, for an id the caller may have spelled
     *     differently; by default the other spelling of an integer node id when the graph holds
     *     only that, so `"34"` reaches node `34`. An edge id is read by the edge writer, which
     *     already takes the number it spells.
     */
    apply(
        mutation: DataMutation,
        writer: GraphWriter,
        resolve: (target: "node" | "edge", id: NodeIdType) => NodeIdType = (target, id) => this.heldId(target, id),
    ): void {
        switch (mutation.kind) {
            case "add-nodes":
                this.addNodes(mutation.records, mutation.idPath, writer);
                return;
            case "add-edges":
                // A graph that already holds edges keeps its direction and where it came from; a
                // declaration that disagrees still reaches applyDeclaredDirection, which logs it.
                if (
                    mutation.directed !== undefined &&
                    (writer.store.builder.edgeCount === 0 || writer.store.builder.directed !== mutation.directed)
                ) {
                    const { directed } = mutation;
                    const statedBy = `"directed": ${String(directed)}`;
                    this.applyDeclaredDirection("data.apply", { directed, statedBy, conflictingEdges: 0 }, writer);
                }

                this.addEdges(
                    mutation.records,
                    {
                        ...(mutation.source === undefined ? {} : { source: mutation.source }),
                        ...(mutation.target === undefined ? {} : { target: mutation.target }),
                        ...(mutation.repeated === undefined ? {} : { repeated: mutation.repeated }),
                    },
                    writer,
                );
                return;
            case "set-attributes":
                for (const id of mutation.ids) {
                    writer.setAttributes(mutation.target, resolve(mutation.target, id), mutation.values);
                }

                return;
            case "update-rows":
                // Values of its own for each row.
                for (const row of mutation.rows) {
                    writer.setAttributes(
                        mutation.target,
                        resolve(mutation.target, row.id),
                        row.values,
                        mutation.replace,
                    );
                }

                return;
            case "remove-nodes": {
                const removed = writer.removeNodes(mutation.ids.map((id) => resolve("node", id)));
                this.host.rowsRemoved(removed.nodes, removed.edges);
                return;
            }

            case "remove-edges": {
                const removed = writer.removeEdges(mutation.ids);
                this.host.rowsRemoved(removed.nodes, removed.edges);
                return;
            }

            default:
                // "clear"
                writer.clear();
                this.reset();
                this.host.cleared();
        }
    }

    /**
     * Carry out one `data.import`: empty the graph first unless it merges, record where the rows
     * came from, and load them. A source missing its name or its options is recorded and nothing
     * is loaded.
     * @param command - The import.
     * @param writer - The command's writer.
     * @param signal - Fires when the import is cancelled; it stops before the next chunk.
     * @returns Settles once the last chunk is written.
     */
    async importSource(
        command: DataImportCommand,
        writer: GraphWriter,
        signal?: AbortSignal,
    ): Promise<ImportOutcome | null> {
        const { type, config } = command.source;
        const loads = type !== undefined && config !== undefined;
        const listed = (writer.graphValue(SOURCES_VALUE) as readonly LoadedSource[] | undefined) ?? [];
        const earlier = command.mode === "merge" ? listed : [];
        const earlierProvenance =
            command.mode === "merge" ? (writer.graphValue(PROVENANCE_VALUE) as Provenance | undefined) : undefined;
        // Read before a replacing load empties the list, so a key is never reused.
        this.sourceSerial = Math.max(this.sourceSerial, ...listed.map((each) => serialOf(each.key)));
        if (loads && command.mode !== "merge") {
            this.apply({ kind: "clear" }, writer);
        }

        const described = describeSource(command.source);
        // A merge under a key the graph already lists (a load's next page, a refresh) adds to that
        // load; it and a joined table leave the graph's own source as it is.
        const same = command.key === undefined ? -1 : earlier.findIndex((each) => each.key === command.key);
        const keepsSource =
            command.mode === "merge" &&
            (same >= 0 || command.origin === "join") &&
            writer.graphValue(SOURCE_VALUE) !== undefined;
        if (!keepsSource) {
            writer.setGraphValues({ [SOURCE_VALUE]: described });
        }

        if (!loads) {
            return null;
        }

        const before = this.heldCounts();

        this.leaveOutUnmatched = command.unmatched === "leave-out";
        this.leftOutEdges = [];
        this.leftOutEnds = null;
        this.loadEdgeLines = command.held === undefined ? null : (command.held.edgeLines ?? []);
        this.duplicateIds = command.duplicateIds ?? "first";
        this.updateExisting = command.mode === "merge" && command.existing === "update";
        // A replacing load is measured against an empty graph, which is what it leaves. Set before
        // the graph is counted, so a measured merge matches its edges against the graph it counts
        // as there, as the real merge does (#935).
        this.measure = command.measure === undefined || command.mode === "merge" ? (command.measure ?? null) : EMPTY;
        this.loadBeganWithNodes = command.mode === "merge" && this.heldCounts().nodes > 0;
        const supplied = { nodes: new Set<NodeId>(), edges: new Set<EdgeId>() };
        this.supplied = supplied;
        this.sealedTally = null;
        try {
            const outcome = await this.addDataFromSource(
                type,
                // The reader leaves style values out of its records when the load draws the file's styles.
                command.styles === undefined ? config : { ...config, styles: command.styles },
                writer,
                signal,
                command.mode !== "merge",
                command.held,
                command.source.name,
            );
            const { report } = outcome;
            const after = this.heldCounts();
            const added = Object.freeze({ nodes: after.nodes - before.nodes, edges: after.edges - before.edges });
            const key: SourceKey = command.key ?? `s${String(++this.sourceSerial)}`;
            const kind: LoadedSourceKind = command.origin ?? (type.startsWith("source:") ? "server" : "file");
            const loaded: LoadedSource = Object.freeze({
                ...described,
                key,
                kind,
                ...(command.joinedOnto === undefined ? {} : { joinedOnto: command.joinedOnto }),
                ...(command.join === undefined ? {} : { join: command.join }),
                ...(command.choices === undefined ? {} : { choices: command.choices }),
                ...(command.mapping === undefined ? {} : { mapping: command.mapping }),
                ...inputOf(command),
                tables: tablesOf(command),
                ...(command.tableRows === undefined ? {} : { tableRows: Object.freeze([...command.tableRows]) }),
                added,
                // What it supplied that the graph holds; `data.sources()` recounts it as the graph changes.
                counts: Object.freeze({ nodes: supplied.nodes.size, edges: supplied.edges.size }),
                ...(this.leaveOutUnmatched && report.unmatched.rows > 0
                    ? {
                          leftOut: Object.freeze({
                              ...report.unmatched,
                              ...(this.leftOutEnds === null ? {} : { endColumns: Object.freeze(this.leftOutEnds) }),
                              edges: Object.freeze(this.leftOutEdges),
                          }),
                      }
                    : {}),
            });
            // What the load saw that the graph does not keep, for `data.issues()`.
            const facts = this.sealedTally === null ? null : loadFactsOf(this.sealedTally, this.leaveOutUnmatched);
            const prior = same < 0 ? undefined : earlier[same];
            const had = prior === undefined ? undefined : earlierProvenance?.[key];
            const nodes = new Set([...(had?.nodes ?? []), ...supplied.nodes]);
            const edges = new Set([...(had?.edges ?? []), ...supplied.edges]);
            const entry: LoadedSource =
                prior === undefined
                    ? loaded
                    : Object.freeze({
                          ...prior,
                          added: Object.freeze({
                              nodes: prior.added.nodes + added.nodes,
                              edges: prior.added.edges + added.edges,
                          }),
                          counts: Object.freeze({ nodes: nodes.size, edges: edges.size }),
                      });
            writer.setGraphValues({
                [SOURCES_VALUE]: Object.freeze(
                    prior === undefined ? [...earlier, entry] : earlier.map((each, at) => (at === same ? entry : each)),
                ),
                [PROVENANCE_VALUE]: withSupplied(earlierProvenance, key, { nodes: [...nodes], edges: [...edges] }),
                ...(facts === null
                    ? {}
                    : {
                          [ISSUES_VALUE]: withLoadFacts(
                              writer.graphValue(ISSUES_VALUE) as IssueState | undefined,
                              key,
                              facts,
                          ),
                      }),
            });
            return outcome;
        } finally {
            this.supplied = null;
            this.sealedTally = null;
            this.leaveOutUnmatched = false;
            this.leftOutEdges = [];
            this.leftOutEnds = null;
            this.loadEdgeLines = null;
            this.duplicateIds = "first";
            this.updateExisting = false;
            this.measure = null;
        }
    }

    /**
     * Record an edge, and the two nodes it names, as supplied by the load in progress.
     * @param edge - The edge's id.
     * @param source - Its source node id.
     * @param target - Its target node id.
     */
    private noteSupplied(edge: EdgeId, source: NodeIdType, target: NodeIdType): void {
        const { supplied } = this;
        if (supplied === null) {
            return;
        }

        supplied.edges.add(edge);
        supplied.nodes.add(source);
        supplied.nodes.add(target);
    }

    /**
     * The id the graph holds a row under, for an id that may be the other spelling of an integer.
     * @param target - Node or edge.
     * @param id - The id as given.
     * @returns The id the graph holds, or the one given when it holds neither spelling.
     */
    private heldId(target: "node" | "edge", id: NodeIdType): NodeIdType {
        if (target === "edge") {
            return id;
        }

        const other = this.hasNode(id) ? undefined : otherIdSpelling(id);
        return other !== undefined && this.hasNode(other) ? other : id;
    }

    /**
     * Whether the graph holds a node, counting a measured load's graph as held.
     * @param id - The node id.
     * @returns True when it does.
     */
    private hasNode(id: NodeIdType): boolean {
        return this.host.hasNode(id) || this.measure?.nodes.has(id) === true;
    }

    /**
     * Adds multiple nodes to the graph
     * @param nodes - Array of node data objects
     * @param idPath - JMESPath expression to extract node ID from data, or undefined for the
     *     configured one
     * @param writer - the graph primitives to write through
     */
    addNodes(
        nodes: readonly Record<string | number, unknown>[],
        idPath: string | undefined,
        writer: GraphWriter,
    ): void {
        this.logger.debug("Adding nodes", { count: nodes.length });

        // Records handed over, counted before any of them is skipped as already known, because
        // this is the number a progress bar is driven by and the number the report contrasts with
        // the nodes the graph ends up holding.
        if (this.loadTally !== null) {
            this.loadTally.nodeRecords += nodes.length;
        }

        // create path to node ids
        const query = idPath ?? this.host.dataConfig().knownFields.nodeIdPath;

        // The ids first, so the ceiling is checked against the nodes this batch would ADD (a
        // re-supplied node costs nothing) and checked before any of them is created: a batch
        // the renderer cannot hold is refused whole, not half-applied.
        // A node an earlier edge created is in the builder, and so in `heldCounts`, without a
        // render object yet: its row is not fresh, or the ceiling counts it twice.
        const { builder } = this.host.store();
        const ids = nodes.map((node) => jmespath.search(node, query) as NodeIdType);
        const fresh = new Set(ids.filter((id) => !this.hasNode(id) && !(isStorableId(id) && builder.hasNode(id))));
        this.refuseAboveCeiling("nodes", this.heldCounts().nodes, fresh.size, DEFAULT_LIMITS.renderCeiling);

        for (const [i, node] of nodes.entries()) {
            const nodeId = ids[i];
            if (this.loadTally !== null && this.loadRowSkipped(nodeId, node, writer, this.loadTally)) {
                continue;
            }

            if (isStorableId(nodeId)) {
                this.supplied?.nodes.add(nodeId);
            }

            if (this.hasNode(nodeId)) {
                if (this.updateExisting && this.host.hasNode(nodeId)) {
                    writer.setAttributes("node", nodeId, frozenRecord(node));
                }

                continue;
            }

            // The store is what gives the node its dense row; INVALID_INDEX comes back for an id
            // graph-format will not take, and the host draws the node anyway.
            // Frozen once, here, so the render object holds the record the graph slice holds.
            const record = frozenRecord(node);
            const { index } = writer.addNode(nodeId, record, readSeedPosition(node));
            this.host.nodeStored(nodeId, record, index);
        }

        if (nodes.length > 0) {
            this.host.nodesArrived(nodes.length);
        }
    }

    /**
     * Count one node record of a load against the load's tally, and say whether it adds no node:
     * a record with no usable id is rejected, and one repeating an id an earlier record of the
     * same load gave is a duplicate, kept out (`"first"`), folded into the first (`"merge"`) or
     * refused (`"refuse"`, `E_DUPLICATE_ID`; a measured load counts it instead).
     * @param id - The id the record gave.
     * @param record - The record.
     * @param writer - The graph primitives to write through.
     * @param tally - The load's tally.
     * @returns True when the record adds no node.
     * @throws A `GraphtyError` with `E_DUPLICATE_ID` under `"refuse"`.
     */
    private loadRowSkipped(
        id: NodeIdType,
        record: Record<string | number, unknown>,
        writer: GraphWriter,
        tally: ImportTally,
    ): boolean {
        if (!isStorableId(id)) {
            tally.rejected++;
            tally.errors.push({ code: "refused-row", params: { rowsAre: "nodes" } });
            tally.refusedRows.push({ rowsAre: "nodes", record: frozenRecord(record) });
            return true;
        }

        if (!tally.nodeIds.has(id)) {
            tally.nodeIds.add(id);
            return false;
        }

        tally.duplicateRows++;
        tally.duplicateIds.add(id);
        if (this.duplicateIds === "first") {
            tally.droppedRows.push({ id, record: frozenRecord(record) });
        }
        if (this.duplicateIds === "refuse" && this.measure === null) {
            throw new GraphtyError({
                code: "E_DUPLICATE_ID",
                source: "data",
                message: `Two node rows give the id ${JSON.stringify(id)}, and the load refuses duplicate ids.`,
                details: { id },
            });
        }

        if (this.duplicateIds === "merge" && this.measure === null) {
            writer.setAttributes("node", id, frozenRecord(record));
        }

        return true;
    }

    /**
     * Add edge records to the graph, resolving their endpoints once for the whole batch.
     *
     * THREE THINGS HAPPEN HERE THAT USED TO HAPPEN ELSEWHERE OR NOT AT ALL.
     *
     * The endpoint spelling is decided once per batch and reported, rather than read from two
     * configured paths whose defaults disagreed with every guide the element ships. A batch whose
     * records answer none of the accepted spellings throws instead of quietly producing a graph
     * with nodes and no edges.
     *
     * A record naming an ordered pair the graph already holds is handed to the repeat policy,
     * which by default KEEPS it as a second edge. It used to be dropped before the store could
     * see it, which is why `statistics().repeatedEdgeCount` has always been zero.
     *
     * A record whose endpoint ids graph-format will not store is REJECTED and counted, rather than
     * becoming a render object with no store row -- which is how an edge ended up permanently
     * visible and unfilterable.
     * @param edges - Array of edge data objects
     * @param options - the endpoint expressions and the repeat policy for this call
     * @param writer - the graph primitives to write through
     * @throws A `GraphtyError` with `E_EDGE_ENDPOINTS_UNRESOLVED` when no spelling answers, and
     *     with `E_DUPLICATE_EDGE` under the `"error"` repeat policy.
     */
    addEdges(
        edges: readonly Record<string | number, unknown>[],
        options: AddEdgesOptions | undefined,
        writer: GraphWriter,
    ): void {
        this.logger.debug("Adding edges", { count: edges.length });

        const { knownFields } = this.host.dataConfig();
        const endpoints = this.endpointsFor(edges, options);
        const policy = options?.repeated ?? knownFields.repeatedEdges;
        const recordIdPath = knownFields.edgeIdPath;
        const weightPath = options?.weight === undefined ? knownFields.edgeWeightPath : options.weight;
        const legacyFallback = options?.weight === undefined;
        const tally = this.loadTally ?? newImportTally();
        let legacyWeights = 0;

        // Decided before any record is stored: a batch the renderer cannot hold is refused whole,
        // so a caller never finds the first part of it held and the rest missing.
        this.refuseAboveCeiling(
            "edges",
            this.heldCounts().edges,
            this.edgesAdded(edges, endpoints, policy, false),
            DEFAULT_LIMITS.edgesDrawn,
        );
        this.refuseAboveCeiling(
            "nodes",
            this.heldCounts().nodes,
            this.endpointNodesAdded(edges, endpoints),
            DEFAULT_LIMITS.renderCeiling,
        );

        const batch: EdgeBatch = { endpoints, policy, recordIdPath, weightPath, legacyFallback, tally };
        for (const edge of edges) {
            if (this.addEdgeRecord(edge, batch, writer)) {
                legacyWeights++;
            }
        }

        if (legacyWeights > 0) {
            // One line per burst, not per edge: this is a deprecation signal, not a per-record
            // warning, and a 50k-edge load would otherwise write 50k of them.
            this.logger.debug("edge weight read from the legacy 'value' key; set data.knownFields.edgeWeightPath", {
                count: legacyWeights,
                edgeWeightPath: weightPath,
            });
        }

        if (this.loadTally === null) {
            // A push of records rather than a file, so there is no enclosing load to seal the
            // report. Seal one here, or `session.data.lastImport()` would answer about the last
            // FILE for a graph whose edges came from a consumer's own array.
            writer.setGraphValues({
                importReport: sealImportReport(tally, {
                    format: "records",
                    endpoints,
                    policy,
                    idPath: recordIdPath,
                    ...this.heldCounts(),
                }),
            });
        }

        if (edges.length > 0) {
            this.host.edgesArrived(edges.length);
        }
    }

    /**
     * Add one edge record of an `addEdges` batch: leave it out, merge it as a repeat, or store it.
     * @param edge - The edge record.
     * @param batch - What the whole batch was resolved to.
     * @param writer - The graph primitives to write through.
     * @returns True when its weight was read from the legacy `value` key.
     */
    private addEdgeRecord(edge: Record<string | number, unknown>, batch: EdgeBatch, writer: GraphWriter): boolean {
        const { endpoints, tally, weightPath } = batch;
        tally.edgeRecords++;
        const srcNodeId = readEndpoint(edge, endpoints.source) as NodeIdType;
        const dstNodeId = readEndpoint(edge, endpoints.target) as NodeIdType;
        if (this.loadTally !== null && this.isUnmatched(srcNodeId, dstNodeId, this.loadTally)) {
            this.keepLeftOut(edge, srcNodeId, dstNodeId, endpoints, tally.edgeRecords);
            tally.edgeIds.push(null);
            return false;
        }

        const weight = resolveEdgeWeight(edge, weightPath, batch.legacyFallback);
        const legacy = weight.source === "legacy";
        if (weight.source !== "default") {
            tally.weightsResolvedFrom = weight.source;
            tally.weightsAttribute = legacy ? "value" : weightPath;
        }

        const recordId = batch.recordIdPath === null ? undefined : readEndpoint(edge, batch.recordIdPath);
        const record = frozenRecord(edge);
        const repeat = { record, weight: weight.weight, sourceId: srcNodeId, targetId: dstNodeId };
        if (this.repeatConsumed(repeat, recordId, batch, writer)) {
            return legacy;
        }

        // The STORE takes the edge now, whether or not the endpoints have render objects:
        // the builder creates a missing endpoint itself, so the snapshot is complete while
        // the scene is still catching up. A load remembers which, to draw them at its end.
        if (this.loadTally !== null) {
            this.rememberMadeEndpoints(srcNodeId, dstNodeId);
        }

        const { index: edgeIndex, edgeId } = writer.addEdge(
            srcNodeId,
            dstNodeId,
            weight.weight,
            record,
            isStorableRecordId(recordId) ? recordId : undefined,
        );
        if (edgeIndex === INVALID_INDEX) {
            // graph-format will not hold an edge between these ids -- most often because the
            // record does not answer the endpoint expressions at all, so both came back null.
            // It gets no row, no counter and no render object, which is what makes "every Edge
            // has a store row" an invariant everything downstream can rely on.
            tally.rejected++;
            tally.errors.push({ code: "refused-row", params: { rowsAre: "edges" } });
            tally.refusedRows.push({ rowsAre: "edges", record });
            tally.edgeIds.push(null);
            return legacy;
        }

        if (isStorableRecordId(recordId)) {
            this.edgesByRecordId.set(recordId, edgeIndex);
            tally.edgesById++;
        } else {
            tally.edgesByPosition++;
        }

        tally.edgeIds.push(edgeIdOf(edgeId));
        this.noteSupplied(edgeIdOf(edgeId), srcNodeId, dstNodeId);
        this.host.edgeStored({ record, sourceId: srcNodeId, targetId: dstNodeId, edgeIndex, edgeId });
        return legacy;
    }

    /**
     * Hand an edge record naming a pair the graph already holds to the repeat policy.
     * @param repeat - The record, its weight and its endpoints.
     * @param repeat.record - The frozen edge record.
     * @param repeat.weight - Its weight.
     * @param repeat.sourceId - Its source id.
     * @param repeat.targetId - Its target id.
     * @param recordId - The record's own id, when the batch reads one.
     * @param batch - What the whole batch was resolved to.
     * @param writer - The graph primitives to write through.
     * @returns True when the policy consumed the record, so it is not stored as a new edge.
     */
    private repeatConsumed(
        repeat: {
            readonly record: Record<string | number, unknown>;
            readonly weight: number;
            readonly sourceId: NodeIdType;
            readonly targetId: NodeIdType;
        },
        recordId: unknown,
        batch: EdgeBatch,
        writer: GraphWriter,
    ): boolean {
        const { policy, tally } = batch;
        const known = this.knownEdgeFor(repeat.sourceId, repeat.targetId, recordId);
        if (known !== null) {
            tally.repeatedSeen++;
            if (this.mergeRepeat(known, repeat, policy, tally, writer)) {
                // The edge it repeats is one this load supplied too.
                this.noteSupplied(edgeIdOf(writer.store.edgeIdAt(known.edgeIndex)), repeat.sourceId, repeat.targetId);
                tally.edgeIds.push(null);
                return true;
            }

            return false;
        }

        if (!this.measuredRepeat(repeat.sourceId, repeat.targetId, recordId)) {
            return false;
        }

        tally.repeatedSeen++;
        return this.countRepeat(policy, tally);
    }

    /**
     * Remember the endpoints of a load's edge that the store will create because no node record
     * named them, so the load draws them at its end.
     * @param ids - The edge's endpoint ids.
     */
    private rememberMadeEndpoints(...ids: NodeIdType[]): void {
        for (const id of ids) {
            if (isStorableId(id) && !this.host.store().builder.hasNode(id)) {
                this.loadMadeEndpoints.add(id);
            }
        }
    }

    /**
     * Count an edge record of a load that names a node no node record holds (nor the graph, for a
     * merge), and say whether the load leaves it out. Checked before the edge is stored, because storing it makes the node.
     * @param source - The source id.
     * @param target - The target id.
     * @param tally - The load's counters.
     * @returns True when the edge is to be left out.
     */
    private isUnmatched(source: NodeIdType, target: NodeIdType, tally: ImportTally): boolean {
        // With no node records and no graph to name, every node comes from the edges: none is missing.
        if (tally.nodeRecords === 0 && !this.loadBeganWithNodes) {
            return false;
        }

        const missing = [source, target].filter(
            (id) => isStorableId(id) && (tally.unmatchedValues.has(id) || !this.hasNode(id)),
        );
        if (missing.length === 0) {
            return false;
        }

        tally.unmatchedRows++;
        for (const id of missing) {
            tally.unmatchedValues.add(id);
        }

        return this.leaveOutUnmatched;
    }

    /**
     * How many nodes this batch of edges would create: endpoints the graph does not hold yet,
     * which the builder creates with the edge. None when unmatched edges are being left out,
     * since an edge naming a missing node is then dropped rather than creating it.
     * @param edges - the batch's records
     * @param endpoints - the endpoint expressions
     * @returns the count
     */
    private endpointNodesAdded(
        edges: readonly Record<string | number, unknown>[],
        endpoints: ResolvedEndpoints,
    ): number {
        const tally = this.loadTally;
        if (tally !== null && this.leaveOutUnmatched && (tally.nodeRecords > 0 || this.loadBeganWithNodes)) {
            return 0;
        }

        const { builder } = this.host.store();
        const fresh = new Set<NodeIdType>();
        for (const edge of edges) {
            for (const id of [readEndpoint(edge, endpoints.source), readEndpoint(edge, endpoints.target)]) {
                if (isStorableId(id) && !builder.hasNode(id) && this.measure?.nodes.has(id) !== true) {
                    fresh.add(id);
                }
            }
        }

        return fresh.size;
    }

    /**
     * Refuse a replacement node set the renderer cannot hold, before the caller removes anything:
     * the node half of {@link Ingest.refuseReplacement}, counted against an emptied graph.
     * @param nodes - the nodes the graph should hold afterwards
     * @param idPath - where a record's id is; the configured node id path when unset
     * @throws A `GraphtyError` with `E_TOO_LARGE` when the new set is past the ceiling.
     */
    refuseNodeReplacement(nodes: readonly Record<string | number, unknown>[], idPath?: string): void {
        const query = idPath ?? this.host.dataConfig().knownFields.nodeIdPath;
        const ids = new Set(nodes.map((node) => jmespath.search(node, query) as unknown));
        this.refuseAboveCeiling("nodes", 0, ids.size, DEFAULT_LIMITS.renderCeiling);
    }

    /**
     * Refuse a replacement edge set the renderer cannot hold, before the caller removes anything.
     *
     * Removing first and letting `addEdges` refuse would leave a host that assigned too many edges
     * with its old edges gone and none of the new ones held, which is neither the graph it had nor
     * the one it asked for. The new batch is counted against an emptied graph, since the old edges
     * are what it replaces; a pending edge, whose endpoints have not arrived, survives the replace.
     * @param edges - the edges the graph should hold afterwards
     * @param replaced - how many held edges the replacement removes
     * @param options - the endpoint expressions and the repeat policy for this call
     * @throws A `GraphtyError` with `E_TOO_LARGE` when the new set is past the ceiling.
     */
    refuseReplacement(edges: Record<string | number, unknown>[], replaced: number, options?: AddEdgesOptions): void {
        const surviving = this.host.store().builder.edgeCount - replaced;
        const policy = options?.repeated ?? this.host.dataConfig().knownFields.repeatedEdges;
        this.refuseAboveCeiling(
            "edges",
            surviving,
            this.edgesAdded(edges, this.endpointsFor(edges, options), policy, true),
            DEFAULT_LIMITS.edgesDrawn,
        );
    }

    /**
     * Keep one left-out edge row with its source (the first {@link LEFT_OUT_KEPT}), with its line
     * when the load reads a draft, and note the columns its ends were read from.
     * @param edge - the row.
     * @param source - its source end.
     * @param target - its target end.
     * @param endpoints - where the ends were read from.
     * @param ordinal - the row's position among the load's edge records, from 1.
     */
    private keepLeftOut(
        edge: Readonly<Record<string | number, unknown>>,
        source: NodeIdType,
        target: NodeIdType,
        endpoints: ResolvedEndpoints,
        ordinal: number,
    ): void {
        if (this.leftOutEdges.length >= LEFT_OUT_KEPT) {
            return;
        }

        const line = this.loadEdgeLines === null ? undefined : (this.loadEdgeLines[ordinal - 1] ?? ordinal);
        // The ends `isUnmatched` just counted as missing, by the same test.
        const missingValues = this.loadTally?.unmatchedValues;
        const missingEnds = (["source", "target"] as const).filter((end) => {
            const id = end === "source" ? source : target;
            return isStorableId(id) && (missingValues?.has(id) === true || !this.hasNode(id));
        });
        this.leftOutEdges.push(leftOutEdge(edge, source, target, endpoints, line, missingEnds));
        const [sourceColumn, targetColumn] = [columnOf(endpoints.source), columnOf(endpoints.target)];
        if (this.leftOutEnds === null && sourceColumn !== null && targetColumn !== null) {
            this.leftOutEnds = { source: sourceColumn, target: targetColumn };
        }
    }

    /**
     * The endpoint expressions this batch is read with, resolved once per load rather than once
     * per batch when a load is in progress.
     * @param edges - the batch's records
     * @param options - the caller's overrides, if any
     * @returns the expressions
     */
    private endpointsFor(
        edges: readonly Record<string | number, unknown>[],
        options: AddEdgesOptions | undefined,
    ): ResolvedEndpoints {
        if (options?.source !== undefined && options.target !== undefined) {
            const declared: ResolvedEndpoints = {
                source: options.source,
                target: options.target,
                resolvedFrom: "declared",
            };
            if (this.loadTally !== null && edges.length > 0) {
                // The load's answer too, so its report (and the columns' roles) name the columns
                // the reader chose rather than the configured defaults it never read.
                this.loadEndpoints = declared;
            }
            return declared;
        }

        if (this.loadEndpoints !== null) {
            return this.loadEndpoints;
        }

        const { knownFields } = this.host.dataConfig();
        const resolved = resolveEndpoints(edges, {
            source: options?.source ?? knownFields.edgeSrcIdPath,
            target: options?.target ?? knownFields.edgeDstIdPath,
        });

        if (this.loadTally !== null && edges.length > 0) {
            // A load is in progress and this is the first chunk that carried edge records, so this
            // answer is the load's answer from here on.
            this.loadEndpoints = resolved;
        }

        return resolved;
    }

    /**
     * The edge a record repeats, or null when it repeats none.
     * @param sourceId - the source endpoint id
     * @param targetId - the target endpoint id
     * @param recordId - the value of `knownFields.edgeIdPath`, when one is configured
     * @returns the existing edge, or null
     */
    private knownEdgeFor(sourceId: NodeIdType, targetId: NodeIdType, recordId: unknown): K | null {
        if (isStorableRecordId(recordId)) {
            // A record identifier is a stronger statement than a repeated pair: the consumer said
            // these two records are the same edge.
            const edgeIndex = this.edgesByRecordId.get(recordId);
            return edgeIndex === undefined ? null : this.host.edgeAt(edgeIndex);
        }

        // The oldest edge between the pair is the one a merge policy folds into, so that `first`
        // and `last` mean what they say when three records name one pair.
        return this.host.edgesBetween(sourceId, targetId)[0] ?? null;
    }

    /**
     * Whether a measured merge's record repeats an edge of the graph it is measured against, which
     * the scratch session does not hold. Matched by pair, as `knownEdgeFor` matches a record with
     * no file id.
     * ponytail: a record with a file id is never matched here, since the graph's file ids are not
     * handed over; hand them over when a consumer reports repeats by id.
     * @param sourceId - the source endpoint id
     * @param targetId - the target endpoint id
     * @param recordId - the record's file id, if any
     * @returns true when it repeats one
     */
    private measuredRepeat(sourceId: NodeIdType, targetId: NodeIdType, recordId: unknown): boolean {
        const pairs = this.measure?.pairs;
        return pairs !== undefined && !isStorableRecordId(recordId) && pairs.has(pairKey(sourceId, targetId));
    }

    /**
     * Count what the repeat policy would do with a measured repeat, writing nothing: there is no
     * edge here to fold it into, and the weight it would take is not part of a report.
     * @param policy - the repeat policy
     * @param tally - the load's counters
     * @returns true when the repeat would not become an edge of its own
     */
    private countRepeat(policy: DuplicatePolicy, tally: ImportTally): boolean {
        const { kind } = decideRepeat(policy, 0, 0);
        if (kind === "add") {
            tally.repeatedKept++;
            return false;
        }

        if (kind === "drop") {
            tally.repeatedDropped++;
        } else if (kind === "merge") {
            tally.repeatedMerged++;
        }

        // "refuse": a real load refuses with E_DUPLICATE_EDGE; a report counts it in `seen`.
        return true;
    }

    /**
     * Apply the repeat policy to one record that names an edge the graph already holds.
     * @param known - the edge already present
     * @param repeat - the repeating record
     * @param repeat.record - the record itself
     * @param repeat.weight - its resolved weight
     * @param repeat.sourceId - the source endpoint id, for the error message
     * @param repeat.targetId - the target endpoint id, for the error message
     * @param policy - what to do about it
     * @param tally - the load's counters
     * @param writer - the graph primitives to write through
     * @returns true when the repeat has been dealt with and must not become an edge of its own
     * @throws A `GraphtyError` with `E_DUPLICATE_EDGE` under the `"error"` policy.
     */
    private mergeRepeat(
        known: K,
        repeat: {
            readonly record: Record<string | number, unknown>;
            readonly weight: number;
            readonly sourceId: NodeIdType;
            readonly targetId: NodeIdType;
        },
        policy: DuplicatePolicy,
        tally: ImportTally,
        writer: GraphWriter,
    ): boolean {
        const { record, weight, sourceId, targetId } = repeat;
        const decision = decideRepeat(policy, writer.store.builder.edgeWeight(known.edgeIndex), weight);
        if (decision.kind === "add") {
            tally.repeatedKept++;
            return false;
        }

        if (decision.kind === "refuse") {
            throw new GraphtyError({
                code: "E_DUPLICATE_EDGE",
                source: "data",
                message:
                    `Two edges run from ${JSON.stringify(sourceId)} to ${JSON.stringify(targetId)}, and ` +
                    `data.knownFields.repeatedEdges is "error". Set it to "keep" to hold both, or to ` +
                    `"first", "last", "sum", "min" or "max" to fold them into one.`,
                details: { source: sourceId, target: targetId, existing: known.edgeIndex, repeat: record },
            });
        }

        if (decision.kind === "drop") {
            tally.repeatedDropped++;
            return true;
        }

        // "the repeat's weight and attributes replace the existing edge's" under `last`. The other
        // three reducers keep the survivor's attributes, because there is no reading of `sum`
        // under which the last record's colour is the group's colour.
        writer.mergeEdge(known.edgeIndex, decision.weight, decision.replaceRecord ? record : null);
        if (decision.replaceRecord) {
            this.host.replaceEdgeRecord(known, record);
        }

        tally.repeatedMerged++;
        return true;
    }

    /**
     * How many edges a batch would add, by the same tests the ingest loop applies.
     *
     * A record whose endpoint ids graph-format will not store adds nothing (the loop rejects it).
     * Under the `keep` policy every other record is an edge. Under a folding policy a record that
     * repeats an edge the graph holds, or a record earlier in the same batch, folds into it and
     * adds nothing; a repeat is named the way `knownEdgeFor` names it, by record id when one is
     * configured and stored, else by the ordered endpoint pair.
     * @param edges - the batch
     * @param endpoints - the batch's endpoint expressions
     * @param policy - the repeat policy the batch is under
     * @param replacing - true when every held edge is about to be removed, so none of them can be
     *     repeated
     * @returns the number of edges the batch would add
     */
    private edgesAdded(
        edges: readonly Record<string | number, unknown>[],
        endpoints: ResolvedEndpoints,
        policy: DuplicatePolicy,
        replacing: boolean,
    ): number {
        const recordIdPath = this.host.dataConfig().knownFields.edgeIdPath;
        const seenIds = new Set<string | number>();
        const seenPairs = new Map<NodeIdType, Set<NodeIdType>>();
        let adding = 0;

        for (const edge of edges) {
            const srcNodeId = readEndpoint(edge, endpoints.source);
            const dstNodeId = readEndpoint(edge, endpoints.target);
            if (!isStorableId(srcNodeId) || !isStorableId(dstNodeId)) {
                continue;
            }

            if (policy !== "keep") {
                const recordId = recordIdPath === null ? undefined : readEndpoint(edge, recordIdPath);
                if (!replacing && this.knownEdgeFor(srcNodeId, dstNodeId, recordId) !== null) {
                    continue;
                }

                const pairs = seenPairs.get(srcNodeId) ?? new Set<NodeIdType>();
                seenPairs.set(srcNodeId, pairs);
                const repeatsBatch = isStorableRecordId(recordId) ? seenIds.has(recordId) : pairs.has(dstNodeId);
                if (repeatsBatch) {
                    continue;
                }

                if (isStorableRecordId(recordId)) {
                    seenIds.add(recordId);
                }

                pairs.add(dstNodeId);
            }

            adding++;
        }

        return adding;
    }

    /**
     * Adopt the direction a file declared, and say out loud when the element could not.
     *
     * The element reports the direction its DATA declares, so that a file which says it is
     * undirected is not counted, measured or offered algorithms as though it were a digraph. What
     * it must never do is overrule the consumer: `data.directed` set to a boolean settles the
     * question and locks the builder, and this reports that rather than fighting it.
     * @param type - the data source type, for the log line
     * @param declaration - what the file said, or null when it said nothing
     * @param writer - the graph primitives to write through
     * @returns true once the question is settled and need not be asked again this import; false
     *     while the source has still declared nothing
     */
    private applyDeclaredDirection(type: string, declaration: DeclaredDirection | null, writer: GraphWriter): boolean {
        if (declaration === null) {
            return false;
        }

        const { store } = writer;
        const outcome: DirectionOutcome = writer.setDirected(declaration.directed, declaration.statedBy);
        if (outcome === "config-wins") {
            this.logger.info("File declares a direction the configuration has already settled", {
                type,
                fileDeclares: declaration.directed,
                statedBy: declaration.statedBy,
                configuredDirected: store.builder.directed,
            });
        } else if (outcome === "edges-present") {
            // Not a warning a consumer can act on by changing their configuration: it means this
            // file arrived into a graph that already had edges, and the direction of a graph that
            // already holds edges is not something graph-format will reinterpret in place.
            this.logger.warn("File declares a direction the graph has already been built with", {
                type,
                fileDeclares: declaration.directed,
                statedBy: declaration.statedBy,
                graphDirected: store.builder.directed,
            });
        }

        // Logged even when the declaration was adopted, and especially then: the file described a
        // graph the element cannot hold, and these are the edges whose own direction it overrode.
        if (declaration.conflictingEdges > 0) {
            this.logger.warn("File mixes directed and undirected edges; the graph holds one direction", {
                type,
                directed: declaration.directed,
                statedBy: declaration.statedBy,
                overriddenEdges: declaration.conflictingEdges,
            });
        }

        return true;
    }

    /**
     * The id a node is held under, in either spelling of an integer id. A node an edge created has a row but no
     * record: it is held all the same.
     * @param id - The id
     * @returns The id the graph holds it under, or undefined
     */
    private heldNode(id: NodeIdType): NodeIdType | undefined {
        const { builder } = this.host.store();
        const held = (one: NodeIdType): boolean =>
            this.host.hasNode(one) || (isStorableId(one) && builder.hasNode(one));
        if (held(id)) {
            return id;
        }

        const other = otherIdSpelling(id);
        return other !== undefined && held(other) ? other : undefined;
    }

    /**
     * Reads every chunk of a source into the graph, publishing the progress after each.
     * @param reader - The source
     * @param load - The format, the cancel signal, the graph primitives and how records name their ids and endpoints
     * @param load.type - The format
     * @param load.signal - Fires when the load is cancelled
     * @param load.writer - The graph primitives to write through
     * @param load.nodeIdPath - Where a node record holds its id, or undefined for the default
     * @param load.endpointOverrides - Where an edge record names its endpoints and weight
     * @param load.onChunk - Told the progress after each chunk
     * @param start - The progress before the first chunk
     */
    private async readChunks(
        reader: ChunkReader,
        load: {
            readonly type: string;
            readonly signal: AbortSignal | undefined;
            readonly writer: GraphWriter;
            readonly nodeIdPath: string | undefined;
            readonly endpointOverrides: AddEdgesOptions;
            readonly onChunk: (progress: LoadProgress) => void;
        },
        start: LoadProgress,
    ): Promise<void> {
        const { type, signal, writer } = load;
        let progress = start;
        // Whether the file's own direction has been dealt with, so the work and the log
        // line happen once per import rather than once per chunk.
        let directionSettled = false;

        for await (const chunk of untilAborted(reader.getData(), signal)) {
            // Nothing is written once the load has been cancelled: its writes are being
            // taken back, and a chunk written after that would outlive them.
            signal?.throwIfAborted();
            // BEFORE this chunk's edges, every time: the builder accepts a direction only
            // while it holds none. Read per chunk rather than once before the loop because
            // a source parses nothing until its first chunk is pulled, so before the loop
            // every source declares null.
            if (!directionSettled) {
                directionSettled = this.applyDeclaredDirection(type, reader.declaredDirection, writer);
            }

            this.addNodes(chunk.nodes, load.nodeIdPath, writer);
            // The endpoint names a caller passed to the SOURCE are honoured here rather
            // than inside each of the seven importers: whatever shape a source produces,
            // the consumer who named the columns named them for the records that come out.
            this.addEdges(chunk.edges, load.endpointOverrides, writer);

            progress = {
                ...progress,
                nodeRecords: progress.nodeRecords + chunk.nodes.length,
                edgeRecords: progress.edgeRecords + chunk.edges.length,
                chunks: progress.chunks + 1,
            };
            load.onChunk(progress);
            this.host.loadProgress(progress);
            this.host.progress?.(loadProgressChange(progress, "progress"));
        }
    }

    /**
     * Report a load that failed while reading and throw what the caller is told.
     * @param type - Data source type identifier
     * @param error - What the read threw
     * @param signal - The load's cancel signal
     * @param progress - How far the load got
     * @throws The error itself when the load was cancelled or the error is coded; otherwise an
     *     Error naming the source and how many chunks it read
     */
    private failLoad(type: string, error: unknown, signal: AbortSignal | undefined, progress: LoadProgress): never {
        // A cancelled load did not fail: whoever cancelled it says why.
        if (signal?.aborted === true) {
            throw error;
        }

        const failure = error instanceof Error ? error : new Error(String(error));
        this.logger.error("Data source loading failed", failure, {
            type,
            chunksProcessed: progress.chunks,
            nodeRecordsLoaded: progress.nodeRecords,
            edgeRecordsLoaded: progress.edgeRecords,
        });

        this.host.loadFailed(type, failure, progress);

        // A coded failure travels out UNCHANGED. Wrapping it in a plain Error destroyed
        // the `code` a caller switches on, so `await graph.addDataFromSource(...)` was
        // the one route where a reader's parse failure arrived as an unclassifiable
        // string while the same failure on the event channel arrived as E_PARSE_FAILED.
        if (isGraphtyError(error)) {
            throw error;
        }

        throw new Error(
            `Failed to load data from source '${type}' after ${progress.chunks} chunks: ${failure.message}`,
        );
    }

    /**
     * Loads data from a registered data source
     * @param type - Data source type identifier
     * @param opts - Options to pass to the data source
     * @param writer - the graph primitives to write through
     * @param signal - Fires when the load is cancelled; it stops at once, even while the source
     *     is still waiting for its next chunk
     * @param replacing - Whether the load replaces the graph, so reading only part of the file
     *     is a failure
     * @param held - Rows a draft already read, loaded instead of reading the source
     * @param name - What the import called the data, for its progress
     * @returns What the load left for the step that applies the file's styles, with its report
     */
    async addDataFromSource(
        type: string,
        opts: object,
        writer: GraphWriter,
        signal?: AbortSignal,
        replacing = false,
        held?: HeldRows,
        name?: string,
    ): Promise<ImportOutcome> {
        this.logger.info("Loading data source", { type, options: opts });

        const startTime = Date.now();
        // Get file size for progress tracking (if available)
        let progress: LoadProgress = {
            format: type,
            fileSize: (opts as { size?: number }).size,
            nodeRecords: 0,
            edgeRecords: 0,
            chunks: 0,
            source: progressSource(opts, name),
        };
        // The first change, published before anything is read, so a watcher sees the load from
        // its first moment.
        this.host.progress?.(loadProgressChange(progress, "progress"));
        let ended = false;
        const end = (outcome: Pick<ProgressChange, "outcome" | "error">): void => {
            if (!ended) {
                ended = true;
                this.host.progress?.(loadProgressChange(progress, "end", outcome));
            }
        };

        // One tally and one endpoint decision for the WHOLE load, however many chunks it arrives
        // in. Cleared in the `finally` below so a failed load cannot leave the next one counting
        // into it, or reading its endpoint answer.
        const tally = newImportTally();
        this.loadTally = tally;
        this.loadEndpoints = null;

        const endpointOverrides = endpointOverridesOf(type, opts, held);
        const nodeIdPath = held?.idPath;

        // Bracketed as ONE load however many chunks it takes, so its edge ordinals are counted
        // over the whole import (design/sets 12.3).
        const { store } = writer;
        store.openLoad();
        try {
            const source = held === undefined ? DataSource.get(type, opts) : null;
            const reader: ChunkReader | null = held === undefined ? source : heldReader(held);
            if (!reader) {
                throw unknownFormat(type);
            }

            try {
                // the progress is kept current chunk by chunk, so a load that fails partway says how far it got
                const onChunk = (read: LoadProgress): void => {
                    progress = read;
                };
                await this.readChunks(
                    reader,
                    { type, signal, writer, nodeIdPath, endpointOverrides, onChunk },
                    progress,
                );

                keepFileGraph(reader, type, writer);

                this.drawMadeEndpoints(writer);
                const errors = reader.getErrorAggregator();
                // The source's own problems come first: it read the file before any record was
                // stored. They reach the report whatever the host does with the event below.
                tally.errors.unshift(...errors.getErrors().map(loadErrorOf));
                tally.errorLimit = errors.getErrorLimit();
                if (errors.getErrorCount() > 0) {
                    this.host.loadErrors(type, errors);
                }
                refuseEmptyOrPartial(type, errors, progress, replacing);

                const duration = Date.now() - startTime;
                const errorCount = errors.getErrorCount();

                // The number a consumer is told is the number of edges the graph HOLDS, which is
                // what `edgesLoaded` has always claimed to be and never was: it counted records
                // handed over, so it reported 254 for a file that produced zero edges. The old
                // meaning survives, under its true name, as `report.counts.edgeRecords`.
                const report = this.sealLoad(
                    type,
                    tally,
                    writer,
                    held === undefined ? undefined : HELD_KINDS.get(held),
                );
                this.sealedTally = tally;
                await this.recordGroups(held === undefined ? source : (HELD_READERS.get(held) ?? null), writer);

                this.logger.info("Data source loading complete", {
                    nodeRecords: progress.nodeRecords,
                    nodesLoaded: report.counts.nodes,
                    edgeRecords: progress.edgeRecords,
                    edgesLoaded: report.counts.edges,
                    endpointsResolvedFrom: report.endpoints.resolvedFrom,
                    duration,
                    chunks: progress.chunks,
                    errors: errorCount,
                });

                this.host.loadComplete(type, report, progress, duration, errorCount);
                end({ outcome: "succeeded" });
                return {
                    reader: held === undefined ? source : (HELD_READERS.get(held) ?? null),
                    edgeIds: Object.freeze([...tally.edgeIds]),
                    report,
                    heldNode: (id) => this.heldNode(id),
                };
            } catch (error) {
                end(failedEnd(error, signal));
                return this.failLoad(type, error, signal, progress);
            }
        } catch (error) {
            end(failedEnd(error, signal));
            throw initFailure(error, type, signal);
        } finally {
            store.closeLoad();
            // Whatever happened, this load is over: the next one probes for itself and counts into
            // its own tally.
            this.loadTally = null;
            this.loadEndpoints = null;
            this.loadMadeEndpoints.clear();
        }
    }

    /**
     * Draw the nodes the load's edges created and no node record of the load named, as a node
     * holding only its id, which is what a file of edges alone means by them. Without this the
     * store holds them and nothing draws them, nor the edges waiting on them.
     * @param writer - the graph primitives to write through
     */
    private drawMadeEndpoints(writer: GraphWriter): void {
        let drawn = 0;
        for (const id of this.loadMadeEndpoints) {
            if (!this.host.hasNode(id)) {
                const record = frozenRecord({ id });
                const { index } = writer.addNode(id, record, null);
                this.host.nodeStored(id, record, index);
                drawn++;
            }
        }

        if (drawn > 0) {
            this.host.nodesArrived(drawn);
        }
    }

    /**
     * Record the groups the file read with no stored position, which the layout places by their
     * members (see `LayoutManager.placeGroups`).
     *
     * ponytail: a merge's groups replace the graph's earlier ones; keep both when merging two
     * nested files matters.
     * @param reader - The reader the load read, or null.
     * @param writer - The graph primitives to write through.
     */
    private async recordGroups(reader: object | null, writer: GraphWriter): Promise<void> {
        const groups = reader === null ? [] : await readGroups(reader, (id) => this.heldNode(id));
        if (groups.length > 0) {
            writer.setGraphValues({ [GROUPS_VALUE]: Object.freeze(groups) });
        }
    }

    /**
     * Freeze one load's counters into the report a consumer reads, and keep it for `lastImport`.
     * @param format - the data source that read the file
     * @param tally - what the load counted
     * @param writer - the graph primitives to write through
     * @param kinds - the kinds the draft gave the rows, when it gave any
     * @returns the report
     */
    private sealLoad(format: string, tally: ImportTally, writer: GraphWriter, kinds?: LoadReport["kinds"]): LoadReport {
        const { knownFields } = this.host.dataConfig();
        const endpoints = this.loadEndpoints ?? {
            // A file with no edge records at all: nothing was probed, so nothing was decided, and
            // saying "source/target" would be reporting a decision that was never made.
            source: knownFields.edgeSrcIdPath ?? "source",
            target: knownFields.edgeDstIdPath ?? "target",
            resolvedFrom: "source/target" as const,
        };

        const sealed = sealImportReport(tally, {
            format,
            endpoints,
            policy: knownFields.repeatedEdges,
            idPath: knownFields.edgeIdPath,
            ...this.heldCounts(),
        });
        const report = kinds === undefined ? sealed : Object.freeze({ ...sealed, kinds });
        writer.setGraphValues({ importReport: report });
        return report;
    }

    /**
     * What the graph HOLDS right now, as the report and the session's own counts both mean it.
     *
     * Read off the builder rather than off the host's render objects, and that is the whole
     * point: an edge endpoint the file never declared as a node is created by the builder, so it
     * is in the graph and in `session.status.counts.nodes` while having no render `Node`. Counting
     * the render objects made the report say two nodes for a load the session reported three for
     * -- one load, two numbers, disagreeing, which is the defect this report exists to end rather
     * than to repeat one level down.
     * @returns the node and edge counts the graph holds
     */
    heldCounts(): { nodes: number; edges: number } {
        const { builder } = this.host.store();
        if (this.measure === null) {
            return { nodes: builder.nodeCount, edges: builder.edgeCount };
        }

        // ponytail: a measured merge adds the graph's edges without folding repeats across the
        // two; fold them here if a merge report under a folding policy has to be exact.
        let nodes = builder.nodeCount;
        for (const id of this.measure.nodes) {
            nodes += builder.hasNode(id) ? 0 : 1;
        }

        return { nodes, edges: builder.edgeCount + this.measure.edges };
    }

    /**
     * Refuse to grow past what the renderer can draw, instead of freezing the tab.
     *
     * WHY A REFUSAL AND NOT A DEGRADED DRAW. The design says that above the render ceiling the
     * element draws a smaller render set, and above `edgesDrawn` it hides edges until the view
     * narrows. Neither exists yet. What exists is a renderer that, past these counts, exhausts
     * the renderer process and produces no further frame -- measured for issue #405 at 18,000
     * nodes / 180,000 edges on an RTX 4070 SUPER, where the renderer process reached 4.7 GB and
     * died while 17,000 / 170,000 loaded in 17 s. Until the degraded draw lands, the honest
     * behaviour at the ceiling is a coded error the consumer can show, so `DEFAULT_LIMITS` is
     * the number the element enforces rather than a number it merely publishes.
     *
     * `E_TOO_LARGE` is the code because the ceiling is a hard limit of this renderer, and the
     * caller's remedy is the one that code names: load a subset.
     * @param of - what is being counted
     * @param held - how many the graph holds already
     * @param adding - how many this call would add
     * @param limit - the most the renderer can draw
     * @throws A `GraphtyError` with `E_TOO_LARGE` when `held + adding` is past the limit
     */
    private refuseAboveCeiling(of: "nodes" | "edges", held: number, adding: number, limit: number): void {
        if (held + adding <= limit) {
            return;
        }

        const { nodes, edges } = this.heldCounts();
        if (this.measure !== null && this.loadTally !== null) {
            this.loadTally.tooLarge ??= { limit, count: held + adding, of, graph: { nodes, edges } };
            return;
        }

        throw new GraphtyError({
            code: "E_TOO_LARGE",
            source: "data",
            message:
                `Loading ${adding.toLocaleString("en-US")} more ${of} would take the graph to ` +
                `${(held + adding).toLocaleString("en-US")}, past the ${limit.toLocaleString("en-US")} ` +
                `this renderer can draw. Load a subset of the graph.`,
            details: { limit, count: held + adding, of, graph: { nodes, edges } },
        });
    }
}

/** The graph a measured replacing load counts as there: none. */
const EMPTY = { nodes: new Set<NodeIdType>(), edges: 0 } as const;

/**
 * What a load that failed before or around its read throws: a coded or cancelled failure
 * unchanged, a read failure already worded, anything else wrapped.
 * @param error - what was thrown
 * @param type - the source type
 * @param signal - fires when the load is cancelled
 * @returns the error to throw
 */
function initFailure(error: unknown, type: string, signal: AbortSignal | undefined): unknown {
    // Same rule one level out: a coded failure is the answer, not something to re-word.
    if (isGraphtyError(error) || signal?.aborted === true) {
        return error;
    }

    // Re-throw if already a processed error
    if (error instanceof Error && error.message.includes("Failed to load data")) {
        return error;
    }

    // Otherwise wrap and throw
    return new Error(
        `Error initializing data source '${type}': ${error instanceof Error ? error.message : String(error)}`,
    );
}

/**
 * Where an edge record names its endpoints and weight: a draft's own names, else the names the caller passed the
 * source. The CSV source reads its own `edgeSource` / `edgeTarget` columns and hands every edge over as `source` /
 * `target`, so reading those names again would find nothing.
 * @param type - The format
 * @param opts - The source's options
 * @param held - Rows a draft already read, or undefined
 * @returns The overrides
 */
function endpointOverridesOf(type: string, opts: object, held: HeldRows | undefined): AddEdgesOptions {
    const named = (type === "csv" ? {} : opts) as { edgeSource?: unknown; edgeTarget?: unknown };
    const source = held?.source ?? named.edgeSource;
    const target = held?.target ?? named.edgeTarget;
    return {
        ...(typeof source === "string" ? { source } : {}),
        ...(typeof target === "string" ? { target } : {}),
        ...(held?.weight === undefined ? {} : { weight: held.weight }),
        ...(held?.repeated === undefined ? {} : { repeated: held.repeated }),
    };
}

/**
 * Refuses a load that loaded nothing, or only part of a file it replaces the graph with. A source that produced no
 * record did not load a graph: it failed, and its draft rolls back rather than recording an empty graph as a load
 * (a file of edges alone is not empty: its endpoints become nodes); a file the parser could not read is not an empty
 * file, since the two have different fixes. The source stops quietly at its error limit, so what was read is only
 * part of the file; a replacing load that swapped a good graph for it did not finish cleanly.
 * @param type - The format
 * @param errors - The source's errors
 * @param progress - What was read
 * @param replacing - Whether the load replaces the graph
 */
function refuseEmptyOrPartial(
    type: string,
    errors: ReturnType<ChunkReader["getErrorAggregator"]>,
    progress: LoadProgress,
    replacing: boolean,
): void {
    const rowErrors = errors.getErrorCount();
    const empty = progress.nodeRecords + progress.edgeRecords === 0;
    const unreadable = empty ? unreadableSource(type, errors.getErrors()) : null;
    if (unreadable !== null) {
        throw unreadable;
    }

    if (empty) {
        throw new GraphtyError({
            code: "E_EMPTY_LOAD",
            source: "data",
            message:
                rowErrors > 0
                    ? `Every row of the ${type} source was rejected (${rowErrors} errors: ` +
                      `${errors.getSummary().message}), so there was nothing to load.`
                    : `The ${type} source held no nodes and no edges, so there was nothing to load. ` +
                      "Check the file, or the format it was read as.",
            details: { format: type, rowErrors },
        });
    }

    if (replacing && errors.hasReachedLimit()) {
        throw new GraphtyError({
            code: "E_PARSE_FAILED",
            source: "data",
            message:
                `The ${type} source stopped after ${rowErrors} rejected rows, its error limit, ` +
                "so only part of it was read and the current graph was kept.",
            details: { format: type, rowErrors },
        });
    }
}

/**
 * Held rows read like a data source: one chunk, then the errors and direction their read found.
 * @param held - The rows.
 * @returns The reader.
 */
function heldReader(held: HeldRows): ChunkReader {
    return {
        declaredDirection: held.declaredDirection,
        // What the file said about the whole graph, from the source that read the rows, so a
        // draft's load keeps it as `data.import` of the same file does.
        declaredGraphValues: HELD_READERS.get(held)?.declaredGraphValues ?? null,
        getErrorAggregator: () => {
            const errors = new ErrorAggregator(held.errorLimit);
            for (const error of held.errors) {
                errors.addError(error);
            }

            return errors;
        },
        getData: () => [{ nodes: held.nodes, edges: held.edges } as DataSourceChunk],
    };
}

/**
 * Keep what the file said about the whole graph with the graph, where a layout chosen for the
 * file reads it.
 * @param reader - The source, once its last chunk is read.
 * @param format - The format it read.
 * @param writer - The command's writer.
 */
function keepFileGraph(reader: ChunkReader, format: string, writer: GraphWriter): void {
    const attributes = reader.declaredGraphValues;
    if (attributes !== null && attributes !== undefined) {
        writer.setGraphValues({ [FILE_GRAPH_VALUE]: Object.freeze({ format, attributes }) });
    }
}

/** What a load reads its chunks from: a data source, or a draft's held rows. */
interface ChunkReader {
    readonly declaredDirection: DeclaredDirection | null;
    /** The file's graph-level attributes, once its last chunk is read; absent for held rows. */
    readonly declaredGraphValues?: Readonly<Record<string, unknown>> | null;
    getErrorAggregator(): ErrorAggregator;
    getData(): AsyncIterable<DataSourceChunk> | Iterable<DataSourceChunk>;
}

/**
 * A source's chunks, ending with the signal's reason as soon as it aborts, rather than when the
 * source next yields: a cancelled load must let go of the queue even when its source is waiting
 * on a slow network or a stalled reader.
 * @param chunks - The source's chunks.
 * @param signal - The load's signal.
 * @yields Each chunk, until the signal aborts.
 */
export async function* untilAborted<T>(
    chunks: AsyncIterable<T> | Iterable<T>,
    signal: AbortSignal | undefined,
): AsyncGenerator<T> {
    if (signal === undefined) {
        yield* chunks;
        return;
    }

    const iterator = Symbol.asyncIterator in chunks ? chunks[Symbol.asyncIterator]() : chunks[Symbol.iterator]();
    let stop: () => void = () => undefined;
    const aborted = new Promise<never>((_, reject) => {
        stop = (): void => {
            const { reason } = signal;
            reject(reason instanceof Error ? reason : new Error(String(reason)));
        };
        signal.addEventListener("abort", stop, { once: true });
    });
    // Rejected only when raced; a handler here keeps an abort nobody awaits from being reported.
    aborted.catch(() => undefined);
    try {
        for (;;) {
            signal.throwIfAborted();
            const next = await Promise.race([iterator.next(), aborted]);
            if (next.done === true) {
                return;
            }

            yield next.value;
        }
    } finally {
        signal.removeEventListener("abort", stop);
        // The source is abandoned; let it close what it holds, without waiting on it.
        Promise.resolve(iterator.return?.()).catch(() => undefined);
    }
}
